insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('air-and-style','Air + Style',array['Flying High Air & Style Contest','Red Bull Air & Style','Quiksilver Air & Style','G-Shock Air & Style','Nokia Air & Style','Billabong Air & Style','Nike 6.0 Air & Style','Oakley & Shaun White Present Air & Style','Opel Air + Style']::text[],'major-contest','independent',1994,2019,'dormant',null,'multiple','global',array['big-air','quarterpipe']::text[],'Started at the Bergisel ski-jump stadium in Innsbruck by Charly Weger and Andrew Hourmont as a single straight-jump contest with a USD 10,000 purse, and grew into the biggest stadium big air of the 1990s and 2000s. A fatal crowd crush after the 4 December 1999 edition killed five people (a sixth died four years later) and led the city of Innsbruck to refuse further events, moving the contest to Seefeld (2000-2004) and then Munich (2005-2007). It was a TTR 6Star and later became its own multi-city tour with stops in Beijing (from 2010) and Los Angeles (from 2015). Shaun White became majority owner in 2014. Edition numbering is inconsistent between sources.',array['https://en.wikipedia.org/wiki/Air_%26_Style','https://de.wikipedia.org/wiki/Air_%26_Style','https://austria-forum.org/af/AustriaWiki/Air_&_Style','https://whitelines.com/events/air-style-innsbruck','https://www.innsbruck.info/blog/en/events/air-and-style2016/','https://www.tt.com/artikel/16237751/das-erbe-des-air-style-snowboarder-fliegen-wieder-auf-bergisel-ab','https://collectivemag.de/air-style-vom-bergisel-stadion-in-die-ganze-welt-pid16548/']::text[],'verified')
