insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('air-nation-freestyle-tour','Air Nation Freestyle Tour',array['Sport Chek Air Nation Freestyle Tour']::text[],'tour-series','Canada Snowboard',null,null,'active',null,'Canada','north-america',array['slopestyle','halfpipe','big-air','rail-jam']::text[],'Canada Snowboard''s national freestyle tour. Recurring stops have included Sun Peaks, Mont Tremblant, Stoneham, Mt St Louis Moonstone, Horseshoe Valley and WinSport Canada Olympic Park in Calgary; the final stop normally carries the national championship.',array['https://www.canadasnowboard.ca/en/events/freestyletour/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[],'verified')
