insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('argentina-snowboard-tour','Argentina Snowboard Tour',array['AST']::text[],'tour-series','Asociacion Argentina de Snowboard (AAS)',null,null,'unconfirmed',null,'Argentina','south-america',array['big-air','slopestyle']::text[],'Described by the WSF as the largest circuit of snowboard events in South America, run by Argentina''s national snowboard association with World Snowboard Tour ranking points. Stops mix urban big airs in Buenos Aires with Patagonian and Andean resorts (Cerro Chapelco, Cerro Bayo, Cerro Catedral, La Hoya); most are open entry, with one invitational.',array['https://www.worldsnowboardfederation.org/the-argentina-snowboard-tour-ast/','https://www.worldsnowboardfederation.org/third-tour-stop-argentina-snowboard-tour-2014/']::text[],'likely')
