insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('atlas-open-val-saint-come','Atlas Open',array['Coupe Val Saint-Come','Royal Rumble']::text[],'legacy-contest','independent',1993,null,'unconfirmed','Val Saint-Come','Canada','north-america',array['other']::text[],'Long-running Quebec contest at Val Saint-Come, first held in 1993 and previously known as the Coupe Val St-Come and the Royal Rumble, per SnowboardQuebec''s history of the sport in the province. Disciplines and end date not sourced.',array['https://www.snowboardquebec.com/histoire/']::text[],'likely')
