insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('audi-nines','Audi Nines',array['Nine Knights','Nine Queens','Knights & Queens','Suzuki Nine Royals','The Nines']::text[],'major-contest','independent',2008,null,'unconfirmed',null,'multiple','europe',array['big-air','hip','slopestyle','other']::text[],'Invitational session founded by Nico Zacek at the Nebelhorn, Oberstdorf in 2008 as a nine-rider freeski gathering. Nine Queens (women) was added at Serfaus-Fiss-Ladis in 2011; Nine Knights moved to Livigno in 2012; snowboarders joined the roster in 2014 when Knights and Queens were first combined. Rebranded Nine Royals in 2017 (Watles) and Audi Nines from 2018 (Soelden/Obergurgl). Riders are judged on custom jump, hip and transition features rather than a fixed course format.',array['https://www.downdays.eu/articles/audi-nines-retrospective/']::text[],'likely')
