insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('audi-snowboard-series','Audi Snowboard Series','{}'::text[],'tour-series','Swiss-Ski',null,null,'unconfirmed',null,'Switzerland','europe',array['slopestyle','halfpipe','boardercross','other']::text[],'The Swiss federation''s national snowboard tour, more than 30 events a season across freestyle, boardercross and race, positioned as a junior pathway to the international elite. The Swiss Championships in all three disciplines close the series.',array['https://www.worldsnowboardfederation.org/audi-snowboard-series/']::text[],'likely')
