insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('bc-snowboard-provincial-series','BC Snowboard Provincial Series',array['Ride On Provincial Series']::text[],'grassroots-contest','BC Snowboard',null,null,'active',null,'Canada','north-america',array['slopestyle','boardercross']::text[],'British Columbia''s provincial competition series, run by BC Snowboard (based in Kelowna) in slopestyle and snowboardcross, with an overall series title. Host resorts in recent seasons have been Big White, Silver Star, Sun Peaks and Whistler Blackcomb. BC Snowboard also sanctions the Neil Edgeworth Memorial Banked Slalom and hosts NorAm, national championship and para World Cup events.',array['https://www.bcsnowboard.com/events/','https://www.bcsnowboard.com/about/','https://www.bcsnowboard.com/2025-event-results/','https://www.bcsnowboard.com/events/provincial-events/']::text[],'verified')
