insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('big-white-para-snowboard-world-cup','Big White Para Snowboard World Cup',array['World Para Snowboard World Cup Big White']::text[],'tour-stop','FIS',null,null,'active','Big White Ski Resort','Canada','north-america',array['boardercross','banked-slalom','team']::text[],'Big White''s annual para-snowboard international, on the TELUS Park course near Kelowna. Big White has supported para snowboarding since 2012 and by the 2018-19 season was hosting for a seventh consecutive year; it also staged the 2017 World Para Snowboard Championships and the 2025 FIS Para Snowboard World Championships, the latter including the first team event in para snowboard history. Governance moved from the IPC to FIS during the period.',array['https://www.canadasnowboard.ca/en/news/?id=1147','https://www.canadasnowboard.ca/en/news/?id=1258','https://www.canadasnowboard.ca/en/news/?id=1259','https://www.bigwhite.com/explore-big-white/blog/mountain-news/fis-pswc-25','https://www.canadasnowboard.ca/en/news/?id=1213']::text[],'verified')
