insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('bomb-hole-cup','The Bomb Hole Cup','{}'::text[],'grassroots-contest','independent',2022,null,'active','Brighton Resort','USA','north-america',array['banked-slalom','jib']::text[],'Two-day event at Brighton Resort, Utah, run with The Bomb Hole podcast: day one is a banked slalom on custom-built berms, day two an open-jam park showdown. Described as the fifth annual event in 2026; the 2027 edition is announced for April 3-4.',array['https://www.brightonresort.com/events/the-bomb-hole-cup','https://www.snowboard.international/features/north-america-snowboard-events-2025-26/','https://thebombhole.com/blogs/bombhole-community/banked-slalom-bomb-hole-cup-2025-at-brighton-utah']::text[],'likely')
