insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('bomber-banked-slalom','Bomber Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Mission Ridge Ski and Board Resort','USA','north-america',array['banked-slalom']::text[],'Community banked slalom at Mission Ridge, Washington, on the Katsuk run at the summit off Chair 2, built by the resort''s park department. Capped at 250 snowboarders across 14 age and gender divisions including Open Pro and Pro Masters. The March 28-29, 2026 edition was billed as the 13th annual.',array['https://www.missionridge.com/event/bomber-banked-slalom/']::text[],'likely')
