insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('bucket-banked-slalom','Bucket Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Winter Park Resort','USA','north-america',array['banked-slalom']::text[],'Banked slalom at Winter Park, Colorado run by the Winter Park Competition Center in memory of local rider and Comp Center alum Ben Lynch, as a fundraiser for the Grand Foundation''s H.O.P.E. Fund. Two runs, best time counts; amateur age divisions plus adaptive and pro categories. Organisers state over $119,305 raised to date.',array['https://www.winterparkresort.com/things-to-do/competition-center/comp-center-events/bucket-banked-slalom']::text[],'likely')
