insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('burton-european-open','Burton European Open','{}'::text[],'major-contest','brand-run',1999,2015,'defunct','Laax','multiple','europe',array['halfpipe','slopestyle']::text[],'Burton''s European flagship and for most of its life the highest-rated (6Star) event on the Swatch TTR World Snowboard Tour in Europe. It began in the Innsbruck area of Austria, moved through Fieberbrunn and Livigno, and settled at Laax, Switzerland from 2005. Burton did not run the event for winter 2016 while re-evaluating its European platform, and the Laax Open took its place and its venue.',array['https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html','https://coolerlifestyle.com/news/events/the-burton-european-open.html','https://onboardmag.com/news/european-news/laax-set-to-host-laax-open-2016.html','https://whitelines.com/events/burton-european-open']::text[],'verified')
