insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('burton-global-open-series','Burton Global Open Series','{}'::text[],'tour-series','brand-run',2006,2011,'defunct',null,'multiple','global',array['halfpipe','slopestyle','quarterpipe','big-air','rail-jam']::text[],'The umbrella that linked Burton''s national Open events into one ranked season, with an overall series title decided at the US Open. Member events across the seasons documented here were the Burton New Zealand Open, Burton Australian Open, Burton Canadian Open, Burton European Open, the Nissan X-Trail Nippon Open in Japan and the Burton US Open. Series champions received USD 100,000 each, described at the time as the largest single payout in competitive snowboarding.',array['https://whitelines.com/archive/news/burton-global-open-series-08-09.html','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://experiencequeenstown.com/events/feature-events/burton-nz-open/','https://www.snowboarder.com/news/2010-burton-new-zealand-open-gears-up','https://whitelines.com/archive/news/mikkel-bang-jenny-jones-win-nissan-x-trail-nippon-open-parkstyle-finals.html']::text[],'likely')
