insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('burton-new-zealand-open','Burton New Zealand Open','{}'::text[],'tour-stop','brand-run',2003,2011,'unconfirmed',null,'New Zealand','oceania',array['halfpipe','slopestyle','quarterpipe']::text[],'The Southern Hemisphere opener of the Burton Global Open Series and, at its peak, the largest snowboard contest in New Zealand. Ran at Snow Park NZ near Wanaka and at Cardrona Alpine Resort, which held the country''s only 22-foot superpipe.',array['https://info.scoop.co.nz/Burton_NZ_Open','https://www.snowboarder.com/news/2010-burton-new-zealand-open-gears-up','https://snowboardmag.com/stories/world-class-riders-arrive-wanaka-nz-2011-burton-new-zealand-open','https://experiencequeenstown.com/events/feature-events/burton-nz-open/']::text[],'likely')
