insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('burton-rail-days','Burton Rail Days','{}'::text[],'major-contest','brand-run',null,null,'unconfirmed','Roppongi Hills','Japan','japan',array['rail-jam','jib']::text[],'Burton''s urban street-snowboarding contest staged in central Tokyo, built from imported snow in the Roppongi Hills arena and run alongside a free public beginner park. The 2015 edition was reported as the fifth.',array['https://www.timeout.com/tokyo/things-to-do/burton-rail-days']::text[],'likely')
