insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('canada-snowboard-junior-nationals','Canada Snowboard Junior National Championships','{}'::text[],'national-championship','Canada Snowboard',null,null,'active',null,'Canada','north-america',array['slopestyle','banked-slalom','halfpipe','parallel-giant-slalom','boardercross','big-air']::text[],'Canada Snowboard''s week-long junior championship, run across Grom, Youth and JR FIS categories in six disciplines. The junior national title event feeding the Junior World Championships team.',array['https://www.canadasnowboard.ca/en/events/nationalsjr/','https://www.canadasnowboard.ca/en/events/']::text[],'verified')
