insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('canada-snowboard-national-championships','Canadian National Snowboard Championships',array['Sport Chek Air Nation Freestyle Nationals','Sports Experts Speed Nation Nationals','Speed Nation Alpine Nationals','Speed Nation Snowboardcross Nationals']::text[],'national-championship','Canada Snowboard',null,null,'active',null,'Canada','north-america',array['halfpipe','slopestyle','big-air','boardercross','parallel-giant-slalom','parallel-slalom','banked-slalom']::text[],'Canada''s national snowboard titles, awarded by Canada Snowboard (the Canadian Snowboard Federation, founded 1991). Since at least the 2010s the championships have been split into separate freestyle, alpine, snowboardcross and para-snowboard events, each hosted at a different resort in the same season and each attached to the corresponding national tour (Air Nation for freestyle, Speed Nation for alpine/SBX/para). No single first year could be sourced.',array['https://www.canadasnowboard.ca/en/events/','https://www.canadasnowboard.ca/en/news/?id=1146','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259','https://en.wikipedia.org/wiki/Canadian_Snowboard_Federation']::text[],'verified')
