insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('canada-winter-games-snowboarding','Snowboarding at the Canada Winter Games','{}'::text[],'national-championship','Canada Games Council',null,null,'active',null,'Canada','north-america',array['parallel-giant-slalom','halfpipe','boardercross','slopestyle']::text[],'The snowboard programme of Canada''s biennial multi-sport games for young athletes, contested by provincial and territorial teams. The Games rotate host provinces; snowboarding has been staged at Mt Sima (Whitehorse 2007), Ski Martock (Halifax 2011), Prince George (2015), Canyon Ski Resort and WinSport Canada Olympic Park (Red Deer 2019) and Mark Arendz Provincial Ski Park at Brookvale (PEI 2023). The first year snowboarding appeared on the programme was not sourced.',array['https://en.wikipedia.org/wiki/Snowboarding_at_the_2011_Canada_Winter_Games','https://en.wikipedia.org/wiki/2007_Canada_Winter_Games','https://en.wikipedia.org/wiki/2015_Canada_Winter_Games','https://en.wikipedia.org/wiki/2019_Canada_Winter_Games','https://en.wikipedia.org/wiki/2023_Canada_Winter_Games']::text[],'verified')
