insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('circuito-bichos','Circuito Bichos','{}'::text[],'grassroots-contest','Anden (Chilean snowboard association, WSF member)',null,null,'unconfirmed',null,'Chile','south-america',array['boardercross','slopestyle','downhill']::text[],'Chile''s under-18 snowboard tour run by the national association Anden, in three age categories (Saltamontes, Grillos, Pulgas) across fun race/boardercross, downhill and slopestyle at the Santiago-area resorts. Anden also ran the professional Circuito RSS (Ranking Ski y Snowboard), a combined freestyle ranking for skiers and snowboarders.',array['https://www.worldsnowboardfederation.org/chile-snowboard-events-2009/']::text[],'likely')
