insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('coupe-quebec-snowboard','Coupe Quebec (Quebec Snowboard Cup)','{}'::text[],'grassroots-contest','Association quebecoise de snowboard',null,null,'active',null,'Canada','north-america',array['slopestyle','boardercross','rail-jam','parallel-giant-slalom','banked-slalom']::text[],'Quebec''s provincial FIS-sanctioned circuit, listed on the SnowboardQuebec calendar as Coupe QC/FIS events. Host hills in the 2025-26 season include Val Saint-Come (rail jam, SBX), Belle-Neige (slopestyle, banked slalom, alpine) and Le Relais. Quebec''s provincial federation was founded in 1987 as the Federation de Surf des Neiges du Quebec.',array['https://www.snowboardquebec.com/calendrier/','https://www.snowboardquebec.com/histoire/']::text[],'likely')
