insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('dirksen-derby','Dirksen Derby','{}'::text[],'grassroots-contest','independent',2007,null,'active','Mt. Bachelor','USA','north-america',array['banked-slalom']::text[],'Hand-built parallel banked slalom race founded by pro snowboarder Josh Dirksen at Mt. Bachelor, Oregon, first run on December 1, 2007 as a fundraiser for Tyler Eklund, a local snowboarder paralysed in a contest earlier that year. It runs a Red (harder) and Green (friendlier) course with combined times, and includes snowboard, sit-ski and splitboard divisions. Beneficiaries have included Oregon Adaptive Sports, Protect Our Winters and the Central Oregon Avalanche Association; the organisers state more than $300,000 has been donated to non-profits and community members.',array['https://www.dirksenderby.com/Race/DirksenDerby/Page-10','https://bendmagazine.com/event/dirksen-derby-18-snowboard-rally-race/2025-12-21/','https://www.bendsource.com/outside/dirksen-derby-rally-race-returns-to-mt-bachelor-for-year-17-22369702/']::text[],'verified')
