insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('european-world-snowboarding-championships','European World Snowboarding Championships','{}'::text[],'legacy-contest','independent',1987,null,'unconfirmed',null,'multiple','europe','{}'::text[],'The rival European world championships of January 1987, run at Livigno, Italy and St Moritz, Switzerland in the same season as the second Breckenridge Worlds. The split between the two claimed world titles is what pushed NASBA and the Snowboard European Association to negotiate a single World Cup circuit.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://www.carvers.it/storia-inglese/','https://snowboarding8090.com/history/']::text[],'likely')
