insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('fis-snowboard-junior-world-championships','FIS Snowboard Junior World Championships',array['FIS Freestyle Ski and Snowboarding Junior World Championships']::text[],'major-contest','FIS',1997,null,'active',null,'multiple','global',array['halfpipe','giant-slalom','parallel-slalom','parallel-giant-slalom','boardercross','big-air','slopestyle','team']::text[],'Annual FIS age-group world championship, first held at Corno alle Scale (ITA) in February 1997. Single-venue through 2015; from 2016 onward routinely split across two to four venues in one season, and combined with freestyle skiing as the FIS Freestyle Ski and Snowboarding Junior World Championships. RESULTS ARCHIVE for a later pass: https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=YYYY&categorycode=WJC (note: the FIS category code is WJC, not JWC), each row linking to per-race pages at https://www.fis-ski.com/DB/general/results.html?sectorcode=SB&raceid=NNNNN.',array['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1997&categorycode=WJC','https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=2026&categorycode=WJC','https://en.wikipedia.org/wiki/FIS_Snowboarding_Junior_World_Championships']::text[],'verified')
