insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('fis-snowboard-world-championships','FIS Snowboard World Championships',array['FIS Snowboarding World Championships']::text[],'major-contest','FIS',1996,null,'active',null,'multiple','global',array['halfpipe','giant-slalom','slalom','parallel-slalom','parallel-giant-slalom','boardercross','big-air','slopestyle','team']::text[],'FIS''s own world championship, first held at Lienz (AUT) in January 1996, two years after FIS took snowboarding under its jurisdiction and while the rival ISF was still running its own world championships. Held in odd-numbered years from 1999 onward (1996 and 1997 were run in consecutive years); skipped in Olympic years. Combined with the FIS Freestyle World Ski Championships from 2015. RESULTS ARCHIVE for a later pass: https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=YYYY&categorycode=WSC (seasoncode = calendar year the championships were held); each event row links to per-race pages at https://www.fis-ski.com/DB/general/results.html?sectorcode=SB&raceid=NNNNN (verified example raceid=22567, 2025 mixed parallel team).',array['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1996&categorycode=WSC','https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=2025&categorycode=WSC','https://en.wikipedia.org/wiki/FIS_Snowboard_World_Championships']::text[],'verified')
