insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('fis-snowboard-world-cup','FIS Snowboard World Cup','{}'::text[],'tour-series','FIS',1994,null,'active',null,'multiple','global',array['halfpipe','giant-slalom','slalom','parallel-slalom','parallel-giant-slalom','boardercross','big-air','slopestyle','team']::text[],'FIS''s season-long snowboard tour. The FIS results database holds no World Cup events before the 1994/95 season; the first World Cup stop on record is Zell am See/Kaprun (AUT), 24-26 November 1994. Edition rows here are SEASONS, keyed to the season end year, not individual stops. RESULTS ARCHIVE for a later pass: season calendars at https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=YYYY&categorycode=WC ; per-race results at https://www.fis-ski.com/DB/general/results.html?sectorcode=SB&raceid=NNNNN ; season Crystal Globe / cup standings at https://www.fis-ski.com/DB/general/cup-standings.html?sectorcode=SB&seasoncode=YYYY&cupcode=WC&disciplinecode=ALL&gendercode=M (or gendercode=L) - all three patterns verified.',array['https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1994&categorycode=WC','https://www.fis-ski.com/DB/general/calendar-results.html?sectorcode=SB&seasoncode=1995&categorycode=WC','https://www.fis-ski.com/DB/general/cup-standings.html?sectorcode=SB&seasoncode=2026&cupcode=WC&disciplinecode=ALL&gendercode=M']::text[],'verified')
