insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('freestyle-ch','freestyle.ch',array['Nescafe Zueri Inline']::text[],'major-contest','independent',1995,null,'unconfirmed','Landiwiese, Zurich','Switzerland','europe',array['big-air']::text[],'Urban big air staged on the Landiwiese on Lake Zurich each September, part of a four-discipline freestyle festival (snowboard, freeski, FMX, skate) drawing around 100,000 spectators. Began in 1995 as Nescafe Zueri Inline; admission became paid in 2005.',array['https://de.wikipedia.org/wiki/Freestyle.ch']::text[],'likely')
