insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('halo-halo-timberline','Halo-Halo','{}'::text[],'grassroots-contest','independent',2023,null,'active','Timberline Lodge and Ski Area','USA','north-america','{}'::text[],'BIPOC-focused summer snowboard gathering on the Palmer snowfield at Timberline, Mt. Hood, Oregon, started in 2023. The 2026 edition is listed for July 10-12. Whether it is judged as a contest or run as a session was not confirmed in this pass.',array['https://www.snowboard.international/features/north-america-snowboard-events-2025-26/']::text[],'likely')
