insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('holy-oly-revival','Holy Oly Revival','{}'::text[],'grassroots-contest','independent',2004,null,'dormant','The Summit at Snoqualmie','USA','north-america',array['quarterpipe','jib','rail-jam']::text[],'A Snowboy Productions grassroots contest at The Summit at Snoqualmie, Washington, built around a quarterpipe and a jib playground (''Tube City'') beneath the Olympia beer can water tower at Summit East. It is a quarterpipe and jib jam, not a banked slalom. Winners received cases of Olympia beer. The Snowboarder''s Journal describes the quarterpipe events as running about eight years.',array['https://www.snowboarder.com/news/7th-annual-holy-oly-the-olympic-hangover-cure','https://www.lib-tech.com/blog/2007/02/14/holy-crap-it%E2%80%99s-the-fourth-annual-holy-oly-revival/','https://thesnowboardersjournal.com/blogs/exclusives/twenty-years-snowboy-productions','https://www.gnu.com/blog/2010/02/24/holy-oly-you-can%E2%80%99t-spell-olympics-without-oly/','http://thesummitcrew.blogspot.com/p/history-of-summit.html']::text[],'likely')
