insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('hot-dawgz-and-hand-rails','Hot Dawgz & Hand Rails','{}'::text[],'grassroots-contest','brand-run',2004,null,'dormant','Bear Mountain','USA','north-america',array['rail-jam','jib']::text[],'Southern California''s pre-season rail jam, run at Bear Mountain (later Snow Summit) in Big Bear Lake, California, on trucked-in man-made snow in September - traditionally the first major rail contest of the North American season. Jam format on urban-style features. First held in 2004; the 2012 edition was the ninth annual and used 130 tons of snow for about 40 pro riders.',array['https://www.firsttracksonline.com/2012/09/07/hot-dawgz-and-hand-rails-pre-season-rail-jam-returns-to-bear-mountain/','https://localfreshies.com/event/hot-dawgz-and-hand-rails-2019-big-bear/']::text[],'likely')
