insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('isf-snowboard-world-championships','ISF World Championships','{}'::text[],'major-contest','ISF (International Snowboard Federation)',1993,null,'defunct',null,'multiple','global',array['halfpipe','giant-slalom','slalom','boardercross']::text[],'The snowboarders'' own world championship, run by the International Snowboard Federation (founded 1989 as the ISA, renamed ISF 1991) and held for the first time at Ischgl, Austria in 1993. From 1996 the ISF and FIS ran rival world championships in the same seasons; the split drove Terje Haakonsen''s boycott of the 1998 Nagano Olympic qualification, since the IOC gave FIS rather than the ISF control of Olympic snowboarding. The ISF filed for bankruptcy in Innsbruck and ceased operating on 22 June 2002, ending the rival championship. NO CENTRAL RESULTS ARCHIVE FOUND - see open_questions.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://en.wikipedia.org/wiki/International_Snowboard_Federation','https://de.wikipedia.org/wiki/International_Snowboarding_Federation','https://en.wikipedia.org/wiki/Terje_H%C3%A5konsen']::text[],'likely')
on conflict (series_id) do update set series_name=excluded.series_name,former_names=excluded.former_names,category=excluded.category,governing_body=excluded.governing_body,first_year=excluded.first_year,last_year=excluded.last_year,status=excluded.status,home_venue=excluded.home_venue,country=excluded.country,region=excluded.region,disciplines=excluded.disciplines,significance=excluded.significance,sources=excluded.sources,confidence=excluded.confidence,updated_at=now();
insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('isf-world-championships','ISF Snowboard World Championships','{}'::text[],'major-contest','ISF',1993,1999,'defunct',null,'multiple','global',array['halfpipe','giant-slalom','slalom','parallel-slalom','boardercross','other']::text[],'The world championship of the International Snowboard Federation, the riders'' governing body of the 1990s. German Wikipedia states four ISF world championships were held between 1993 and 1999. The ISF''s own successor (WSF) dates the federation''s founding to 1990, when five nations and 120 racers formed it; English Wikipedia instead dates it to 1989 in Vancouver as the International Snowboard Association, renamed ISF in 1991. The ISF ceased operations on 22 June 2002.',array['https://de.wikipedia.org/wiki/Snowboard-Weltmeisterschaft','https://en.wikipedia.org/wiki/International_Snowboard_Federation','https://www.worldsnowboardfederation.org/inside-wsf/history/','https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://www.carvers.it/storia-inglese/']::text[],'likely')
on conflict (series_id) do update set series_name=excluded.series_name,former_names=excluded.former_names,category=excluded.category,governing_body=excluded.governing_body,first_year=excluded.first_year,last_year=excluded.last_year,status=excluded.status,home_venue=excluded.home_venue,country=excluded.country,region=excluded.region,disciplines=excluded.disciplines,significance=excluded.significance,sources=excluded.sources,confidence=excluded.confidence,updated_at=now();
insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('isf-world-snowboarding-championships','ISF World Snowboarding Championships',array['Motorola ISF World Championships']::text[],'major-contest','ISF (International Snowboard Federation)',1993,null,'defunct',null,'multiple','global',array['halfpipe','boardercross','other']::text[],'The rider-run International Snowboard Federation''s world championship, and the counterweight to the FIS world championships of the 1990s. The first was held at Ischgl, Austria in 1993. By 1999/2000 the title was contested across a season-long Motorola ISF World Pro Tour rather than a single meeting. The ISF was dissolved in 2002.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://www.sportcal.com/pressreleases/the-motorola-isf-world-championships-1999-2000-halfpipe-davos-sui/','https://de.wikipedia.org/wiki/Snowboard-Weltmeisterschaften']::text[],'likely')
