insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('jla-mammoth-banked-slalom','JLA Mammoth Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Mammoth Mountain','USA','north-america',array['banked-slalom']::text[],'Banked slalom at Mammoth Mountain honouring the legacy of pro snowboarder Jeff Anderson (JLA). Local Freshies notes it celebrated its 10th anniversary in 2013 and lists the 2026 edition for February 27-March 1.',array['https://localfreshies.com/banked-slalom-event-showcase/']::text[],'likely')
