insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('jsba-all-japan-snowboard-championships','JSBA All Japan Snowboard Championships',array['JSBA全日本スノーボード選手権大会']::text[],'national-championship','JSBA (Japan Snowboarding Association)',1983,null,'active',null,'Japan','japan',array['halfpipe','slopestyle','boardercross','big-air','giant-slalom','dual-slalom']::text[],'Japan''s national amateur snowboard championship, run by the JSBA and reached through regional and G1 qualifying events. The 41st edition in 2023 is described on the JSBA site as annual since 1983; the JSBA''s own history page states the first All Japan championship was staged in 1982 at Kyowa Ski Resort, Akita, with the previous year''s North American champion invited. Programme covers halfpipe, slopestyle, snowboard cross, straight jump (big air), giant slalom and dual slalom; venues rotate and a single edition often splits across two resorts.',array['https://www.jsba.or.jp/information/history/','https://www.jsba.or.jp/ajsc_site/ajsc41/','https://www.jsba.or.jp/ajsc_site/ajsc43/']::text[],'likely')
