insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('jsba-all-japan-snowboard-technical-championships','JSBA All Japan Snowboard Technical Championships',array['JSBA全日本スノーボードテクニカル選手権大会']::text[],'national-championship','JSBA (Japan Snowboarding Association)',null,null,'active',null,'Japan','japan',array['other']::text[],'JSBA championship judging overall riding ability rather than tricks or times, in Alpine and Freestyle categories for men and women plus a club team competition. Regional qualifiers run three events, the national final five. The 33rd edition was held in the 2025/26 season.',array['https://www.jsba.or.jp/education/ajstc/','https://www.jsba.or.jp/ajstc_site/ajstc33/']::text[],'likely')
