insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('kaunertal-opening','Kaunertal Opening',array['KTO']::text[],'legacy-contest','independent',1986,null,'active','Snowpark Kaunertal, Kaunertaler Gletscher','Austria','europe',array['jib','rail-jam','other']::text[],'Glacier season-opening snowboard gathering in the Tirol, combining a rider contest with a brand testival, mini-ramp and jib sessions. Onboard and World Snowboard Guide both call the 2015 edition the 30th and Whitelines calls 2022 the 37th year, which places the first edition in 1986. The 2015 edition revived the mini-ramp after a 15-year absence and ran a Legends Invitational session.',array['https://onboardmag.com/news/snowboarding-events/30th-kaunertal-opening-event-recap.html','https://www.worldsnowboardguide.com/news/30th-kaunertal-opening-2015.html','https://whitelines.com/snowboard-culture/snowboard-events/kto-2022-kaunertal-opening-is-back.html']::text[],'likely')
