insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('king-of-the-mountain-ski-cooper','King of the Mountain (Ski Cooper)','{}'::text[],'legacy-contest','independent',1981,null,'unconfirmed','Ski Cooper','USA','north-america',array['slalom','other']::text[],'Widely cited as the first modern snowboard contest, held in April 1981 at Ski Cooper, Leadville, Colorado, at a time when almost no resort would host snowboarders. Tom Sims and Jake Burton Carpenter both attended.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://en.wikipedia.org/wiki/Snowboarding']::text[],'likely')
