insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('laax-open','LAAX OPEN','{}'::text[],'major-contest','FIS',2016,null,'active','LAAX','Switzerland','europe',array['halfpipe','slopestyle']::text[],'Direct successor to the Burton European Open at the same resort. Launched for winter 2016 after Burton stepped back from the BEO, keeping the open-entry format, the core organising team and the Laax superpipe. It joined the FIS Snowboard World Cup in its second year and now also runs a freeski slopestyle World Cup alongside the snowboard events.',array['https://onboardmag.com/news/european-news/laax-set-to-host-laax-open-2016.html','https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/','https://laaxopen.com/en/hall-of-fame/','https://laaxopen.com/en/about-laax-open/']::text[],'verified')
