insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('mt-baker-last-stand-rail-jam','Last Stand Rail Jam','{}'::text[],'grassroots-contest','independent',null,null,'active','Mt. Baker Ski Area','USA','north-america',array['rail-jam']::text[],'End-of-season freestyle contest at Mt. Baker Ski Area, listed by the ski area as open to all skill levels. Scheduled for Saturday, April 3, 2027 in the 2026-27 season.',array['https://www.mtbaker.us/events/']::text[],'likely')
