insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('mt-baker-legendary-banked-slalom','Mt. Baker Legendary Banked Slalom',array['Sims Open','Mt. Baker Banked Slalom']::text[],'legacy-contest','independent',1985,null,'active','Mt. Baker Ski Area','USA','north-america',array['banked-slalom']::text[],'The oldest continuously run snowboard contest in the United States, first held in 1985 on the natural gully at Mt. Baker known as the Natural Halfpipe. Organised by Bob Barci, Tom Sims, Jeff Fulton and the Mt. Baker Hard Core riders after they approached ski area manager Duncan Howat in 1984. Winners receive a duct-tape trophy and an embroidered Carhartt jacket rather than prize money; the event turned down big-money sponsorship and television in the early 1990s and returned to a grassroots format. Entry is capped (400 racers in 2025) and it is widely described as the predecessor of boardercross.',array['https://en.wikipedia.org/wiki/Mt._Baker_Legendary_Banked_Slalom','https://www.mountbakerexperience.com/stories/30-years-of-the-legendary-banked-slalom,339','https://unofficialnetworks.com/2024/01/30/legendary-banked-slalom-history/','https://lbs.mtbaker.us/results/honor-roll/','http://www.cascadiadaily.com/2025/feb/04/mt-baker-ski-area-prepares-for-world-famous-snowboard-race/','https://snowboarding8090.com/mt-baker-lbs/','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://localfreshies.com/mt-baker-banked-slalom/']::text[],'verified')
