insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('mt-baker-ravens-edge-dual-slalom','Raven''s Edge Dual Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Mt. Baker Ski Area','USA','north-america',array['dual-slalom']::text[],'Two-day ski and snowboard dual slalom at Mt. Baker Ski Area, open to all ages and abilities. Scheduled for April 10-11, 2027 in the 2026-27 season.',array['https://www.mtbaker.us/events/']::text[],'likely')
