insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('mt-spokane-banked-slalom','Mt. Spokane Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Mt. Spokane Ski & Snowboard Park','USA','north-america',array['banked-slalom']::text[],'Banked slalom on a hand-built course at Mt. Spokane, Washington, run by the non-profit ski area. Two timed runs, best run counts; open to both snowboarders and skiers with Pro/Open and amateur age divisions. The 2025 edition was held March 8.',array['https://www.mtspokane.com/bankedslalom']::text[],'likely')
