insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('nate-chute-banked-slalom','Nate Chute Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Whitefish Mountain Resort','USA','north-america',array['banked-slalom']::text[],'Banked slalom at Whitefish Mountain Resort, Montana, associated with the Nate Chute Foundation. Local Freshies calls it the ''second longest running Banked Slalom in the US''; the same page also calls the Neil Edgeworth Memorial at Big White the ''second oldest'', so the claim needs checking. The 2026 edition is listed for March 14-15.',array['https://localfreshies.com/banked-slalom-event-showcase/']::text[],'likely')
