insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('national-collegiate-snowboarding-championships','National Collegiate Snowboarding Championships','{}'::text[],'national-championship',null,1989,null,'unconfirmed',null,'USA','north-america','{}'::text[],'First collegiate snowboard championship in the United States, held at Stratton Mountain, Vermont in December 1989.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[],'likely')
