insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('national-snurfing-championships','National Snurfing Championships',array['World Snurfing Championship','National Snurf Championship','National Snurfer Championship','National Snow Surfing Championship']::text[],'legacy-contest',null,1968,1984,'defunct',null,'USA','north-america',array['downhill','slalom','other']::text[],'The Snurfer contests at Muskegon, Michigan are the direct ancestor of snowboard competition. The Michigan Snowboard Museum timeline dates the first World Snurfing Championship to 19 February 1968 at Blockhouse Hill in Muskegon State Park. The series ran at Blockhouse Hill through 1979 and then at Pando, and it is the event Jake Burton Carpenter entered in 1979 with a bindinged board, which prompted a separate open division.',array['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html','https://en.wikipedia.org/wiki/Snowboarding']::text[],'likely')
