insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('neil-edgeworth-memorial-banked-slalom','Neil Edgeworth Memorial Banked Slalom',array['Inland Snowboard Big White Banked Slalom']::text[],'grassroots-contest','independent',1987,null,'active','Big White Ski Resort','Canada','north-america',array['banked-slalom']::text[],'Big White''s banked slalom, first run in the 1987/88 season as the Inland Snowboard Big White Banked Slalom and renamed after local rider Neil Edgeworth, who was killed by an avalanche in France in 1997. Run in a natural gully beside the Ridge Rocket chair and later at TELUS Park, with pro, amateur (age groups from 11-and-under to 60+) and para divisions on the same course. Now organised with BC Snowboard; the organisers describe it as a gathering rather than a competition. 320 entrants in 2017, 255 in 2025.',array['https://www.bigwhite.com/explore-big-white/blog/mountain-news/nebs-26yrs-tradition','https://www.bigwhite.com/explore-big-white/blog/telus-park/big-white-hosts-20th-annual-neil-edgeworth-banked-slalom','https://www.bigwhite.com/explore-big-white/blog/telus-park/25-years-nebs','https://www.bcsnowboard.com/wp-content/uploads/2026-27th-Annual-NEBS-Event-Information.March-20-22-2026.pdf']::text[],'verified')
