insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('nescafe-champs-leysin','NESCAFE Champs',array['Nescafe Open Champs','Champs Open Leysin','Nokia Champs','The Champs','Nescafé Champs']::text[],'legacy-contest','independent',1991,null,'unconfirmed','Leysin','Switzerland','europe',array['halfpipe','slopestyle']::text[],'Described by the World Snowboard Federation and World Snowboard Guide as the oldest snowboard event in Europe. First held in 1991 at Leysin; Nescafe was title sponsor 1994-2006 and returned in 2010. The contest spent three seasons in Valais before returning to Leysin in 2010 and reached its 20th edition in 2011. Later editions ran a hybrid slopestyle course combining a halfpipe with kickers, rails and a wallride.',array['https://www.worldsnowboardfederation.org/nescafe-open-champs-in-leysin-2010-the-oldest-european-snowboard-event/','https://www.worldsnowboardguide.com/news/cilka-sadar---lucien-koch-win-2011-champ-in-leysin.html','https://snowboarding.transworld.net/news/get-ready-for-the-nescafe-champs-in-leysin-switzerland-march-6-10/']::text[],'verified')
