insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('nippon-open','Nissan X-Trail Nippon Open','{}'::text[],'tour-stop','brand-run',null,null,'unconfirmed','ALTS Bandai','Japan','japan',array['halfpipe','slopestyle']::text[],'The Japanese stop of the Burton Global Open Series, held at ALTS Bandai in Fukushima Prefecture and reported at the time as one of Japan''s most popular snowboard events, drawing over 40,000 spectators. Winners took 8,000 points toward the Burton Global Open Series championship.',array['https://whitelines.com/archive/news/japan-beckons-riders-for-5-star-nissan-x-trail-nippon-open.html','https://whitelines.com/archive/news/mikkel-bang-jenny-jones-win-nissan-x-trail-nippon-open-parkstyle-finals.html','https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[],'likely')
