insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('niseko-moiwa-banked-slalom','Niseko Moiwa Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Niseko Moiwa Ski Resort','Japan','japan',array['banked-slalom']::text[],'Late-March banked slalom at Niseko Moiwa in Hokkaido, run across five divisions including snowskate and ski classes and a snowboard masters category for riders 43 and over.',array['https://niseko-moiwa.jp/ja/news/2025/03/10/532/']::text[],'verified')
