insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('north-alps-banked-slalom','North Alps Banked Slalom','{}'::text[],'tour-series','independent',null,null,'active',null,'Japan','japan',array['banked-slalom']::text[],'Described as Japan''s only banked slalom series: three races in the Hakuba valley, Nagano, at Hakuba Iwatake, Tsugaike Mountain Resort and Hakuba Happo-one. The Tsugaike round (BANKED SLALOM TGK) is the second race and by 2026 had grown to two days with 260 riders a day and ski, snowboard, snowbike and parent-child divisions.',array['https://steep.jp/en/custom/tsugaike-banked-slalom/']::text[],'likely')
