insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('north-american-snowboarding-championships','North American Snowboarding Championships','{}'::text[],'legacy-contest',null,null,null,'unconfirmed',null,'Canada','north-america','{}'::text[],'An early continental championship run in western Canada in the mid-to-late 1980s. TransWorld SNOWboarding''s first issue (fall 1987) covered a North American Championships at Banff; a snowboarding history project places a 1985 North American Championships at Calgary. Whether these are the same series is not established.',array['https://www.snowboarder.com/transworld-snowboarding-archive/three-decades-transworld-snowboarding-part-1-1987-1996','https://snowboarding8090.com/history/']::text[],'likely')
