insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('norwegian-snowboard-championships','Norwegian Snowboard Championships',array['NM i snowboard']::text[],'national-championship',null,null,null,'unconfirmed',null,'Norway','europe',array['halfpipe','slopestyle','big-air','boardercross']::text[],'Norway''s national snowboard titles, contested across several venues in a season and, in the TTR era, carrying 3-Star ranking status. The winner of the combined title receives the King''s Cup (Kongepokal). The 2010/11 Norwegian season carried 15 TTR/WSF 1-3 Star events in big air, slopestyle and halfpipe.',array['https://www.worldsnowboardfederation.org/the-3star-ttr-norwegian-championships/']::text[],'likely')
