insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('nz-snowboard-nationals','New Zealand Snowboard Nationals','{}'::text[],'national-championship','Snow Sports NZ',null,null,'unconfirmed',null,'New Zealand','oceania',array['halfpipe','slopestyle','big-air','boardercross','other']::text[],'New Zealand''s national snowboard titles, run by Snow Sports NZ as the culmination of a season-long National Park and Pipe series of sanctioned events. Cardrona Alpine Resort hosts the Cardrona NZ Freeski and Snowboard Junior Nationals annually and is naming sponsor of the national Park and Pipe team.',array['https://www.sporty.co.nz/snowsportsnz/sports/snowboarding']::text[],'likely')
