insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('oakley-girl-sessions-ruka','Oakley Girl Sessions',array['Oakley Girlsessions']::text[],'tour-stop','independent',2004,null,'unconfirmed','Ruka BatteryPark, Ruka','Finland','europe',array['slopestyle','halfpipe','team']::text[],'Women-only snowboard event at Ruka in Finnish Lapland, run as a Swatch TTR 3-Star alongside open-ability sessions, a team contest and a freeski slopestyle. The 2010 edition was the seventh, placing the first around 2004. Enni Rukajarvi won the 2009 edition before her international breakthrough.',array['https://www.worldsnowboardfederation.org/7th-edition-of-oakley-girlsessions-at-ruka-finland-8-11-4-2010/']::text[],'likely')
