insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('olympic-snowboarding','Snowboarding at the Olympic Winter Games','{}'::text[],'major-contest','IOC (sport governed at the Games by FIS)',1998,null,'active',null,'multiple','global',array['halfpipe','giant-slalom','parallel-giant-slalom','parallel-slalom','boardercross','slopestyle','big-air','team']::text[],'Snowboarding was admitted to the Olympic programme for the 1998 Nagano Winter Games with men''s and women''s giant slalom and halfpipe. The programme has grown to 11 medal events by 2022 and 2026. RESULTS ARCHIVE for a later pass: Olympedia gives a complete per-Games event index at https://www.olympedia.org/editions/{edition_id}/sports/SBD (verified edition ids: 46=1998, 47=2002, 49=2006, 57=2010, 58=2014, 60=2018, 62=2022, 72=2026, 70=2020 Winter YOG, 73=2024 Winter YOG); each event on that index links to a full finishing-order page.',array['https://www.olympedia.org/sports/SBD','https://www.olympedia.org/editions/46/sports/SBD','https://www.olympedia.org/editions/72/sports/SBD']::text[],'verified')
