insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('oneill-evolution','O''Neill Evolution','{}'::text[],'major-contest','TTR',2006,2013,'defunct','Davos','Switzerland','europe',array['halfpipe','slopestyle','big-air']::text[],'Brand-run TTR contest at Davos, launched in 2006 and held every year for eight years to 2013 before O''Neill withdrew from major events. It carried 6Star status and was one of the first top-tier events to run women''s and men''s fields in both halfpipe and slopestyle (2011). It ran a week-long format in early January, closing with a big air or halfpipe final at the Bolgen slope below the Jakobshorn.',array['https://www.worldsnowboardguide.com/news/no-o-neill-evolution-in-davos-this-season.html','https://www.boardshop.de/boardmag/snowboard/news/oneill-evolution-2011-in-davos-vom-2-bis-8-januar_aid_16198.html','https://www.boardshop.de/boardmag/snowboard/news/ttr-6star-contest-oneill-evolution-in-davos-live-webcast-04-09-01-2010_aid_16337.html','https://www.worldsnowboardguide.com/events/o-neill-evolution-2013.html','https://whitelines.com/events/oneill-evolution']::text[],'verified')
