insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('ontario-snowboard-provincial-series','Ontario Snowboard Provincial Series','{}'::text[],'grassroots-contest','Ontario Snowboard',null,null,'active',null,'Canada','north-america',array['halfpipe','slopestyle','big-air','giant-slalom','parallel-giant-slalom']::text[],'Ontario''s provincial series across freestyle and alpine disciplines, run by Ontario Snowboard (the Association of Ontario Snowboarders, based in Collingwood). Host clubs and resorts include Alpine Ski Club, Horseshoe Valley Resort, Beaver Valley and Craigleith Ski Club. Ontario Snowboard also delivers the snowboard programme for the 2027 Canada Winter Games.',array['https://www.ontariosnowboard.ca/']::text[],'verified')
