insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('op-pro-snowboarding','OP Pro of Snowboarding','{}'::text[],'legacy-contest','brand-run',null,null,'defunct',null,'USA','north-america',array['halfpipe','giant-slalom']::text[],'Ocean Pacific''s snowboard contest, one of the surf-brand events that carried prize money into snowboarding in the late 1980s. The Snowboarder/TransWorld 1980s timeline records an OP Pro of Snowboarding at June Mountain, California in 1989.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[],'likely')
