insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('pacwest-banked-slalom','PacWest Banked Slalom','{}'::text[],'grassroots-contest','independent',2022,null,'active','Summit East, The Summit at Snoqualmie','USA','north-america',array['banked-slalom']::text[],'Banked slalom created in 2022 by Marcel Dolak at Summit East, the former PacWest ski area at Snoqualmie Pass, Washington - a venue that hosted Northwest snowboard contests and jams through the 1980s to 2000s (the Good and Plenty Jam, Urban Circus Jumpfest) and where Craig Kelly and Jamie Lynn rode. The 2026 edition offered 21 divisions from ages 6 to 60+.',array['https://www.summitatsnoqualmie.com/events/pacwest-banked-slalom','https://thesnowboardersjournal.com/blogs/exclusives/pacwest-banked-slalom-2022','https://thesnowboardersjournal.com/blogs/exclusives/pacwest-banked-slalom-2024']::text[],'verified')
