insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('pleasure-jam','Pleasure Jam',array['Horsefeathers Pleasure Jam','O''Neill Pleasure Jam']::text[],'major-contest','independent',2003,null,'unconfirmed','Superpark Dachstein, Dachstein Glacier','Austria','europe',array['slopestyle']::text[],'European season-opening slopestyle contest on the Dachstein glacier, run by QParks (which has managed the Superpark since 2004) as the first stop of the QParks Snowboard Tour and, in TTR years, a Swatch TTR 4-Star. The 2015 edition was billed as Vol. 13, which places the first edition in 2003.',array['https://www.worldsnowboardfederation.org/pleasure-jam-vol-13-postponed/','https://www.worldsnowboardfederation.org/horsefeather-pleasure-jam-09-in-dachstain/','https://www.worldsnowboardfederation.org/qparks-snowboard-tour-set-for-201617/']::text[],'likely')
