insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('qparks-snowboard-tour','QParks Snowboard Tour','{}'::text[],'tour-series','independent (QParks)',2009,null,'unconfirmed',null,'multiple','europe',array['slopestyle','rail-jam','jib']::text[],'Amateur freestyle snowboard tour across QParks-built parks in Austria, Germany, Italy and Switzerland, with professional judging and a shared prize pot (EUR 40,000 in 2016/17). The 2016/17 season was described as its seventh, placing the first season around 2009/10. It opens each year with the Pleasure Jam on the Dachstein.',array['https://www.worldsnowboardfederation.org/qparks-snowboard-tour-set-for-201617/']::text[],'likely')
