insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('rattlesnake-banked-slalom','Rattlesnake Banked Slalom','{}'::text[],'grassroots-contest','independent',2023,null,'active','Buck Hill','USA','north-america',array['banked-slalom']::text[],'Snowboard-only banked slalom at Buck Hill, Minnesota - the Twin Cities hill where Lindsey Vonn learned to race. Fastest of two runs, six divisions (Junior 15 and under, Open 16-39, Master 40+, each split by gender), each capped at 25 riders. The March 2, 2025 edition was the third annual.',array['https://buckhill.com/events/rattlesnake-banked-slalom-2025/']::text[],'likely')
