insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('rey-del-park','Rey del Park',array['Lippi Rey del Park','King of the Park']::text[],'major-contest','independent',null,null,'unconfirmed','El Colorado','Chile','south-america',array['slopestyle']::text[],'Described by the World Snowboard Federation as the biggest freestyle event in Chile, held in the terrain park at El Colorado above Santiago and open to skiers as well as snowboarders. The 2012 running was the eighth edition, which places the first around 2005, and was the first year it counted towards the WSF South America Tour.',array['https://www.worldsnowboardfederation.org/viii-rey-del-park-el-colorado-chile/','https://www.worldsnowboardfederation.org/lippi-king-of-the-park-in-el-colorado-chile/']::text[],'likely')
