insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('roxy-chicken-jam','Roxy Chicken Jam',array['Chicken Jam']::text[],'major-contest','TTR',null,null,'defunct',null,'multiple','global',array['halfpipe','slopestyle','big-air']::text[],'All-female contest run by Roxy, described as the only women''s-only events to hold Swatch TTR 6Star accreditation. It ran a European stop in December and a US stop in late March; the US final was the season-defining event for the TTR women''s ranking, with the women''s TTR world champion decided there. Wikipedia dates the event to the 2004-05 season.',array['https://en.wikipedia.org/wiki/Chicken_Jam','https://www.worldsnowboardfederation.org/ttr-women-tour-announced/','https://coolerlifestyle.com/news/everything-you-wanted-to-know-about-the-ttr-but-were-afraid-to-ask.html']::text[],'likely')
