insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('shakedown-snowboard-games','Shakedown',array['Empire Shakedown','Ride Shakedown','The Original Snowboard Games']::text[],'major-contest','independent',2002,2015,'defunct','Mont Saint-Sauveur','Canada','north-america',array['slopestyle','big-air','rail-jam','jib']::text[],'Founded in 2002 by Brendan O''Dowd and Patryck Bernier at Mont Saint-Sauveur in the Laurentians, explicitly to fill the gap left by the end of the WestBeach Classic. Jam format scored 50/50 between big air and street/rail, with riders calling tricks in advance and no repeats. 6,000 spectators and a $10,000 winner-take-all purse in year one, later 25,000 spectators and $50,000 across the top ten; broadcast on TSN, RDS and TVA Sports. Seb Toutant won the pro category here in 2006 at age 13. Empire was title sponsor 2002-2008, Ride Snowboards from 2009, under which the event expanded to the USA (2010) and Europe (2011).',array['https://en.wikipedia.org/wiki/Shakedown_(Snowboard_Games)','https://kingsnowboard.com/blogs/uncategorized/timepiece-shakedown','https://www.snowboardquebec.com/histoire/']::text[],'verified')
