insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('showcase-showdown','Showcase Showdown','{}'::text[],'grassroots-contest','independent',1997,null,'active','Whistler Blackcomb','Canada','north-america',array['big-air','halfpipe','rail-jam']::text[],'Shop contest started by Showcase Snowboards in Whistler Village (opened 1989 as Showcase Tennis, later the largest Burton dealer in North America) and billed as Canada''s longest-running snowboard competition. Held on Blackcomb; by the 2010s a big air with a $10,000 pro men''s purse plus a berth in the WSSF Monster Energy Shred Show, with a junior rail jam added in 2015.',array['https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx','https://snowboardmag.com/news/whistler-blackcombs-18th-annual-showcase-showdown-returns-march-14','https://whistlermuseum.org/2023/03/07/selling-snowboards/','https://www.straight.com/life/402596/showcase-showdown-and-whistler-ski-and-snowboard-fest-go-far-beyond-rock-n-snow']::text[],'likely')
