insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('slash-the-mass-banked-slalom','Slash the Mass Banked Slalom','{}'::text[],'grassroots-contest','independent',null,null,'active','Snowmass','USA','north-america',array['banked-slalom']::text[],'Snowboard-only banked slalom at Snowmass, Colorado, run by Aspen Snowmass with age divisions from 12-and-under to 40-plus plus Open/Pro men and women. The edition listed on the resort''s site is billed as the 12th annual and was cancelled for snow conditions; the year of that edition is not stated on the page.',array['https://www.aspensnowmass.com/visit/events/slash-the-mass-banked-slalom']::text[],'likely')
