insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('snoboard-shop-north-american-championships','The Snoboard Shop North American Snowboarding Championships',array['North American Snowboarding Championships']::text[],'legacy-contest','independent',1985,1988,'defunct',null,'Canada','north-america',array['other']::text[],'The first Canadian snowboard contest of any scale, run by Ken Achenbach out of The Snoboard Shop in Calgary - the world''s first snowboard-only shop. Held on the May long weekend at Sunshine Village in Banff with a $20,000 purse, it was one of the most important early North American contests; a photo of Dave Achenbach from the event ran on the cover of the first issue of TransWorld Snowboarding. Sunshine pulled out mid-season in 1988 and Mt Norquay took the event over, putting Norquay on the TransWorld cover. Disciplines run each year were not sourced.',array['https://www.snowboardquebec.com/histoire/','https://kootenaymountainculture.com/meet-the-men-who-brought-snowboarding-to-canada/','https://banffnorquay.com/blog/lift-lines-humans-of-norquay-a-hill-makes-space-for-snowboarding/','https://www.snowboarder.com/snowboarders/fathers-of-snowboarding-ken-achenbach']::text[],'likely')
