insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('snowboard-jamboree','Snowboard Jamboree',array['Stoneham Snowboard Jamboree','Quebec City Snowboard Jamboree']::text[],'major-contest','FIS',2006,null,'unconfirmed',null,'Canada','north-america',array['big-air','slopestyle','halfpipe']::text[],'Quebec''s flagship freestyle snowboard festival, produced by Gestev and split between Stoneham Mountain Resort and a downtown Quebec City big air site (Ilot Fleurie). It carried FIS Snowboard World Cups and, from 2014, 5-star World Snowboard Tour status; the 2014 edition was billed as the 9th Jamboree and the 15th World Cup held in Quebec. It hosted the 2013 FIS Snowboarding World Championships and moved to an all-urban big air format in 2016. Whether it has run since 2019 was not established.',array['https://www.skicanada.org/snowboard-world-cup-returns-stoneham-quebec-city/','https://www.skicanada.org/stoneham-snowboard-jamboree-now-world-cup-event/','https://snowboardmag.com/news/quebec-city-snowboard-jamboree-festival-back-for-10th-edition','https://www.snowboardquebec.com/2014/snowboard-jamboree/','https://www.firsttracksonline.com/2015/10/01/quebecs-world-cup-jamboree-goes-urban/']::text[],'verified')
