insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('snowboard-masters-japan','SNOWBOARD MASTERS',array['SBM']::text[],'grassroots-contest','independent',null,null,'active',null,'Japan','japan',array['banked-slalom','slalom','other']::text[],'Japanese mass-participation contest normally judged on freeride performance plus an obstacle slalom, open to Japan-resident riders aged 18 and over with reduced entry for JSBA and PSA members. In 2024 it ran instead as SBM BANKED+, a straight banked slalom, because conditions prevented building the usual courses.',array['https://steep.jp/en/custom/sbmbanked/']::text[],'likely')
