insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('snowboard-world-cup-pre-fis','Snowboard World Cup (pre-FIS)','{}'::text[],'tour-series','NASBA / Snowboard European Association, later ISF',1987,null,'defunct',null,'multiple','global',array['halfpipe','slalom','giant-slalom']::text[],'The first international snowboard tour, created when NASBA (formed 8 March 1987) partnered with the Snowboard European Association to merge the rival American and European world championships into one circuit. Multiple accounts say the first season ran two events in the United States and two in Europe, with O''Neill, Suzuki and Swatch as sponsors. Later absorbed into the ISF World Tour.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://www.carvers.it/storia-inglese/','https://snowbrains.com/snowboarding-pioneer-paul-alden-dies-aged-89/','https://www.tetonvalleynews.net/townnews/sport/a-founding-figure-of-organized-competitive-snowboarding-has-passed/article_db455d7f-ed68-46f1-a971-050e55e36410.amp.html']::text[],'likely')
