insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('speed-nation-alpine-tour','Speed Nation Alpine Tour',array['Sport Chek Speed Nation Alpine Tour']::text[],'tour-series','Canada Snowboard',null,null,'active',null,'Canada','north-america',array['parallel-giant-slalom','parallel-slalom']::text[],'Canada Snowboard''s national alpine (racing) tour. Recurring stops have included Le Relais at Lac-Beauport, Toronto Ski Club at Collingwood, Alpine Ski Club and Blue Mountain, with Blue Mountain hosting the alpine national championship in 2018 and 2019.',array['https://www.canadasnowboard.ca/en/events/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[],'verified')
