insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('speed-nation-sbx-tour','Speed Nation Snowboardcross Tour',array['Sport Chek Speed Nation Snowboardcross Tour']::text[],'tour-series','Canada Snowboard',null,null,'active',null,'Canada','north-america',array['boardercross']::text[],'Canada Snowboard''s national snowboardcross tour. Recurring stops have included Big White, Panorama, Sun Peaks, Craigleith, Horseshoe Valley, Mont Orignal and Mont Sainte-Anne, with a stop designated as the Canadian snowboardcross championship.',array['https://www.canadasnowboard.ca/en/events/sbxtour/','https://www.canadasnowboard.ca/en/news/?id=1213','https://www.canadasnowboard.ca/en/news/?id=1259']::text[],'verified')
