insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('spring-battle','Spring Battle',array['Absolut Park Spring Battle']::text[],'major-contest','independent',2002,null,'active','Absolut Park, Flachauwinkl','Austria','europe',array['slopestyle','rail-jam']::text[],'Spring park contest at Absolut Park Flachauwinkl, running since 2002 per the organiser''s own site. Originally a Swatch TTR event; by 2025 a WSF Elite Level Event feeding the World Snowboard Points List, judged from multi-day single-take follow-cam footage rather than live runs.',array['https://www.absolutpark.com/en/spring-battle-25/','https://onboardmag.com/news/snowboarding-events/absolut-park-spring-battle-2007-snowboard.html']::text[],'likely')
