insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('stylewars-australia','StyleWars',array['Oakley StyleWars']::text[],'major-contest','independent',null,null,'unconfirmed','Falls Creek, Victoria','Australia','oceania',array['slopestyle','rail-jam']::text[],'Australia''s biggest Swatch TTR tour event, founded and run by Richard Hegarty at Falls Creek in Victoria. Rated 3-Star in 2007 and 4-Star by 2008-2011; in 2011 the organiser referred to ''the past 10 years running'', implying a start around 2001-2002. Sebastien Toutant''s 2009 win here made him the youngest rider to top the TTR ranking.',array['https://www.worldsnowboardfederation.org/events-in-australia/','https://www.worldsnowboardfederation.org/stylewars-2011-australia/','https://www.worldsnowboardfederation.org/?s=Stylewars']::text[],'likely')
