insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('suomi-tour','Suomi Tour','{}'::text[],'tour-series','Finnish Snowboard Association (FSA)',null,null,'unconfirmed',null,'Finland','europe',array['slopestyle','halfpipe']::text[],'The Finnish Snowboard Association''s national contest tour, with Grom, Rookie and Open divisions plus a Burton Riglet park and coaching for first-time competitors. The tour''s regional stops culminate in the Finnish national championships (SM) at Ruka.',array['https://www.worldsnowboardfederation.org/suomi-tour-finland/']::text[],'likely')
