insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('tenjin-banked-slalom','Tenjin Banked Slalom','{}'::text[],'grassroots-contest','independent',2012,null,'unconfirmed','Tanigawadake Tenjindaira Ski Resort','Japan','japan',array['banked-slalom']::text[],'Mt Baker-inspired banked slalom on Mt Tanigawa above Minakami, Gunma, reached by tram and organised by former pro rider Yosuke Nishida of the TJ brand. First run in 2012; by 2017 it drew over 400 people across two days and opened with a ceremony praying for safety on an avalanche-prone mountain.',array['https://www.worldsnowboardfederation.org/wsf-support-banked-slalom-all-around/','https://www.worldsnowboardfederation.org/2015-tenjin-banked-slalom/','https://www.worldsnowboardfederation.org/photogallery-and-results-from-2016-tenjin-banked-slalom/','https://www.worldsnowboardfederation.org/tenjin-banked-slalom-2017/']::text[],'verified')
