insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('the-arctic-challenge','The Arctic Challenge',array['Oakley Arctic Challenge']::text[],'major-contest','independent',1999,2014,'dormant',null,'Norway','europe',array['halfpipe','quarterpipe','slopestyle','freeride','other']::text[],'Founded in 1999 by Norwegian pros Terje Haakonsen and Daniel Franck as a rider-run alternative to contests they saw as shaped by TV coverage and major sponsors. It ran at locations north of the Arctic Circle in its early years before moving to the Oslo area from 2006. It was one of the events the TTR tour was built around and was the only 6Star-rated event owned by a professional rider, with a USD 100,000 purse and 1000 TTR points to the winner. Terje set a quarterpipe air record of 9.8 m above the lip at the 2007 edition, beating Heikki Sorsa''s 9.3 m from 2001.',array['https://en.wikipedia.org/wiki/Arctic_Challenge','https://www.the-house.com/portal/the-history-of-the-oakley-arctic-challenge/','https://www.the-arctic-challenge.com/','https://whitelines.com/archive/news/terje-haakonsen-releases-new-statement-on-the-arctic-challenge.html']::text[],'verified')
