insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('the-brits','The BRITS',array['British Snowboard Championships','British Snowboard and Freeski Championships']::text[],'national-championship','independent',1990,null,'active',null,'United Kingdom','europe',array['slopestyle','halfpipe','big-air','boardercross','banked-slalom','rail-jam']::text[],'Britain''s national snowboard championships, founded in 1990 and described by the World Snowboard Federation as Europe''s longest established winter snowsports festival (20th birthday in 2009). Started in Scotland, spent roughly three decades at Alpine host resorts including Laax, and returned to Cairngorm in 2023 for the first time in 32 years. Now run alongside the British Freeski Championships.',array['https://planetski.eu/2023/02/02/the-brits-heads-back-to-its-roots-in-scotland/','https://www.worldsnowboardfederation.org/news/the-brits-2009-in-laax/']::text[],'verified')
