insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('toyota-big-air','Toyota Big Air','{}'::text[],'major-contest','independent',1997,2014,'defunct','Sapporo','Japan','japan',array['big-air']::text[],'Long-running Japanese stadium big air, 18 editions from 1997 to 2014, normally held around 11 February and shifted to late January or late February in Olympic years. Held at the Makomanai open-air stadium in Sapporo (branded Makomanai Sekisui Heim Stadium from 2007) for its first 15 editions, then moved indoors to the Sapporo Dome from 2012 with a 36 m temporary in-run scaffold. The organising office announced on 30 September 2014 that the event would not continue after the 18th edition.',array['https://en.wikipedia.org/wiki/Toyota_Big_Air','https://ja.wikipedia.org/wiki/TOYOTA_BIG_AIR']::text[],'verified')
