insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('transworld-team-challenge','TransWorld Team Challenge',array['TransWorld Team Shoot Out']::text[],'grassroots-contest','independent',1999,null,'defunct','Snow Summit','USA','north-america',array['team']::text[],'Team-format contest launched by TransWorld SNOWboarding at Snow Summit, California in 1999 and won by the Atlantis team; TransWorld says it ran for ten years before becoming the Team Shoot Out.',array['https://www.snowboarder.com/news/three-decades-transworld-snowboarding-part-2-1997-2006']::text[],'likely')
