insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('transworld-transam','TransWorld TransAm','{}'::text[],'tour-series','independent',2003,null,'defunct',null,'USA','north-america','{}'::text[],'TransWorld SNOWboarding''s travelling American amateur contest series, launched in 2003 and run for 13 seasons. TransWorld names Lucas Magoon, Chas Guldemond, Gabi Viteri and Matt Ladley among its winners. Stops, disciplines and per-year dates were not sourced in this pass.',array['https://www.snowboarder.com/news/three-decades-transworld-snowboarding-part-2-1997-2006']::text[],'likely')
