insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('us-open-snowboarding','Burton US Open Snowboarding Championships',array['National Snowsurfing Championships','National Snowboarding Championships','US Open Snowboarding Championships']::text[],'major-contest','brand-run',1982,2020,'dormant',null,'USA','north-america',array['slalom','downhill','halfpipe','superpipe','quarterpipe','slopestyle','big-air','boardercross','rail-jam','other']::text[],'The longest-running snowboard contest in the sport and the flagship of Burton''s contest programme. Burton''s own history page dates the lineage to the 1982 National Snowsurfing Championships at Suicide Six, Vermont; other archives treat that Paul Graves event as a separate contest and date the US Open lineage to Jake Burton Carpenter''s 1983 National Snowboarding Championships at Snow Valley, Vermont. The event took the US Open name at Stratton Mountain in 1985, ran there through 2012, moved to Vail in 2013, and was last held in 2020; the 2021 edition was cancelled and Vail confirmed it would not return.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.burton.com/en-us/blogs/the-burton-blog/13-firsts-us-open-snowboarding-championships','https://thesnowpros.org/2024/09/from-the-archives-great-moments-in-snowboarding-history-part-2/','https://www.firsttracksonline.com/2002/03/03/the-u-s-open-snowboarding-championships-back-to-where-it-all-began/','https://www.vaildaily.com/news/is-vails-burton-us-open-competition-gone-for-good/','http://www.snowboardinginsouthernvermont.com/woodstock-1982.html','https://www.snurferboy.com/nationalchampionship','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[],'verified')
