insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('us-snowboarding-grand-prix','Toyota U.S. Grand Prix',array['U.S. Snowboarding Grand Prix','Chevrolet U.S. Snowboarding Grand Prix','Sprint U.S. Snowboarding Grand Prix']::text[],'tour-series','FIS',1996,null,'active',null,'USA','north-america',array['halfpipe','superpipe','slopestyle','big-air']::text[],'U.S. Ski & Snowboard''s domestic halfpipe (later halfpipe and slopestyle) series and the official qualifying series for the U.S. Olympic snowboard team. Founded 1996; described by U.S. Snowboarding as the first domestic competition series to offer equal prize money to men and women. Now run as FIS World Cup stops under Toyota title sponsorship.',array['https://en.wikipedia.org/wiki/U.S._Snowboarding_Grand_Prix','https://www.aspensnowmass.com/visit/events/toyota-us-grand-prix','https://www.fis-ski.com/snowboard-park-and-pipe/news/2021-22/toyota-us-grand-prix-halfpipe-world-cup-at-copper-mountain-snowboard']::text[],'verified')
