insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('usasa-national-championships','USASA National Championships',array['United States Amateur Snowboarding Association National Championships']::text[],'national-championship','USASA',1990,null,'active','Copper Mountain','USA','north-america',array['halfpipe','slopestyle','boardercross','giant-slalom','slalom','rail-jam']::text[],'The season-ending national championships of USASA, the American grassroots amateur snowboard (and, since 2011, freeski) association founded in 1988 by Chuck Allen with $500 of seed money from TransWorld SNOWboarding. The first Nationals were held in 1990; early editions moved between small mountains in Vermont and Maine and hills in Oregon and California, and Copper Mountain, Colorado has been the permanent home since 2008. Athletes qualify through regional series. USASA states nearly all of the U.S. Olympic snowboard and freeski team began in its events.',array['https://usasa.org/about-us/history/','https://usasa.org/national-championships/','https://www.townoffrisco.com/event/copper-mountain-events/usasa-snowboard-national-championships/','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[],'verified')
