insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('usasa-regional-series','USASA Regional Series','{}'::text[],'tour-series','USASA',null,null,'active',null,'USA','north-america',array['halfpipe','slopestyle','boardercross','giant-slalom','slalom','rail-jam']::text[],'The regional competition structure that feeds the USASA National Championships. USASA groups 32 local divisions nationwide into five regional series - Rockies (Utah, Arizona, Colorado, New Mexico), Western (Alaska, Mt. Hood area of Oregon, Lake Tahoe), Central (Great Lakes), Eastern (New York and the Adirondacks) and New England. Each local division runs its own season of events; this is the layer at which most American amateur snowboarders actually competed.',array['https://usasa.org/regional/','https://www.townoffrisco.com/event/copper-mountain-events/usasa-snowboard-national-championships/']::text[],'verified')
