insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('vans-triple-crown-of-snowboarding','Vans Triple Crown of Snowboarding','{}'::text[],'tour-series','brand-run',null,null,'defunct',null,'United States','north-america',array['halfpipe','big-air','boardercross']::text[],'Vans-run three-stop North American tour with an overall men''s and women''s title decided across the series. The 1999/2000 season ran boardercross, big air and halfpipe at Breckenridge, snowboard cross and halfpipe at Mount Seymour in British Columbia, and halfpipe at Sierra-at-Tahoe, with a USD 10,000 overall prize.',array['https://www.mountainzone.com/snowboarding/2000/vans/index.html','https://www.mountainzone.com/snowboarding/2000/vans/breckenridge/']::text[],'likely')
