insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('waengl-taengl','Vans Waengl Taengl',array['Aesthetiker Waengl Taengl']::text[],'legacy-contest','independent',2002,null,'dormant','Mayrhofen, Zillertal','Austria','europe',array['team','slopestyle']::text[],'Week-long team-based snowboard ''contest-ival'' in Mayrhofen run by the Austrian Aesthetiker crew, blending a team snowboard contest with team skate, music and art. The World Snowboard Federation gives 2002 as the founding year and 2012 as the tenth-anniversary edition. The Aesthetiker announced a break for 2013 to rework the format.',array['https://www.vice.com/de/article/waengl-taengl-ueberrollt-mayrhofen/','https://www.worldsnowboardfederation.org/news/the-asthetikers-announce-a-break-from-the-wangl-tangl-in-2013/']::text[],'likely')
