insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('westbeach-classic','WestBeach Classic',array['WestBeach Invitational','WestBeach Snowboard Classic']::text[],'legacy-contest','brand-run',1989,2000,'defunct','Whistler Blackcomb','Canada','north-america',array['halfpipe','big-air']::text[],'The defining Canadian spring snowboard contest of the late 1980s and 1990s, sponsored by Vancouver brand WestBeach and produced by The Masters Group. Ross Rebagliati won the 1989 halfpipe and landed the cover of TransWorld Snowboarding. It was folded into the World Ski & Snowboard Festival from the mid-1990s; the 1997 WestBeach Invitational Big Air drew over 8,000 spectators at the base of Whistler Mountain. Moved to the May long weekend in 2000 and was not held in 2001 after WestBeach redirected its funding to the World Snowboarding Championship.',array['https://www.piquenewsmagazine.com/local-sports/westbeach-classic-not-on-2459602','https://whistlermuseum.org/2024/04/09/wssf-the-beginning/','https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx','https://parrot-point-8fe3.squarespace.com/stories/pipe-dreams']::text[],'verified')
