insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('whistler-blackcomb-fis-snowboard-world-cup','FIS Snowboard World Cup - Whistler Blackcomb','{}'::text[],'tour-stop','FIS',null,null,'unconfirmed','Whistler Blackcomb','Canada','north-america',array['boardercross','halfpipe','big-air','parallel-giant-slalom','slopestyle']::text[],'Whistler Blackcomb''s international race stop. A December 2001 World Cup ran snowboard cross, two halfpipes, alpine and big air over six days. Whistler Blackcomb also staged the 2005 FIS Snowboarding World Championships (16-22 January 2005), the first time that championship was held outside Europe, and continues to host FIS-level slopestyle competitions.',array['https://www.piquenewsmagazine.com/local-sports/whistler-the-year-in-sports-2461092','https://en.wikipedia.org/wiki/FIS_Snowboarding_World_Championships_2005','https://www.fis-ski.com/DB/general/event-details.html?sectorcode=SB&eventid=55267&seasoncode=2024']::text[],'likely')
