insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('winsport-calgary-world-cup','WinSport Canada Olympic Park FIS World Cup (Calgary)',array['Halfpipe Rodeo FIS Ski & Snowboard World Cup']::text[],'tour-stop','FIS',null,null,'active','WinSport Canada Olympic Park','Canada','north-america',array['halfpipe','slopestyle']::text[],'Calgary''s World Cup stop on the 1988 Olympic site, run on WinSport''s 22-foot halfpipe and slopestyle course. Branded the Halfpipe Rodeo in 2019. The same venue hosts Canada Snowboard''s Air Nation halfpipe national championship and hosted snowboarding at the 2019 Canada Winter Games.',array['https://www.canadasnowboard.ca/en/news/?id=1256','https://www.canadasnowboard.ca/en/news/?id=1259','https://olympic.ca/2019/10/24/winter-competitions-coming-to-canada-in-2019-20/','https://www.canadasnowboard.ca/en/events/freestyletour/nationalsfree/']::text[],'verified')
