insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('winter-dew-tour','Winter Dew Tour',array['AST Dew Tour (winter)','Winter Dew Tour presented by Toyota']::text[],'tour-series','brand-run',2008,2024,'defunct',null,'USA','north-america',array['superpipe','slopestyle','jib','team','other']::text[],'Mountain Dew-backed, NBC-broadcast winter park-and-pipe tour launched for the 2008-09 season with three stops. Reduced to a single mountain championship from the 2012-13 season. Based at Breckenridge for eleven editions (2008-2018), then Copper Mountain (2020-2024). Served as a US Ski & Snowboard Olympic qualifying event in several seasons. Discontinued after the March 2024 edition.',array['https://en.wikipedia.org/wiki/Dew_Tour','https://news.vailresorts.com/2008-11-21-WINTER-DEW-TOUR-TO-VISIT-BRECKENRIDGE-RESORT,-DEC-18-21','https://news.vailresorts.com/2018-06-07-Winter-Dew-Tour-Returns-to-Breckenridge-December-13-16,-2018','https://www.mensjournal.com/adventure/winter-dew-tour-heads-to-copper-mountain-colorado-february-6-9-2020/']::text[],'verified')
