insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('winter-games-nz','Winter Games NZ',array['New Zealand Winter Games','100% Pure New Zealand Winter Games']::text[],'major-contest','independent (Winter Games NZ Trust)',2009,2024,'defunct',null,'New Zealand','oceania',array['halfpipe','slopestyle','big-air']::text[],'The Southern Hemisphere''s largest snow sports event, staged in the Southern Lakes district around Wanaka and Queenstown. Biennial from 2009 to 2017, annual from 2018; 11 editions in total. Over its life it hosted 23 FIS Snowboard World Cups and 20 FIS Freeski World Cups plus ANC Cups, Freeride World Qualifiers and FIS Junior World Championships, and from 2020 added the athlete-focused Obsidian team format. Wound up on 23 January 2025, the trust citing event delivery costs, the NZ sponsorship and media market, international federation sanctioning fees and prize money indexed to European currencies.',array['https://planetski.eu/2025/01/23/winter-games-nz-ends/','https://www.wintergamesnz.kiwi/about-1','https://en.wikipedia.org/wiki/New_Zealand_Winter_Games']::text[],'verified')
