insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('winter-x-games','Winter X Games (Aspen)',array['Winter X Games','X Games Aspen']::text[],'major-contest','ESPN',1997,null,'active','Buttermilk Mountain, Aspen','USA','north-america',array['halfpipe','superpipe','slopestyle','big-air','boardercross','jib','rail-jam','dual-slalom','other']::text[],'ESPN''s made-for-broadcast winter contest, first held 1997 at Big Bear Lake, California. Moved to Crested Butte (1998-99) and Mount Snow (2000-01) before settling at Buttermilk Mountain in Aspen from 2002 onward. Introduced the superpipe format to snowboard contests and, from 2019, the Knuckle Huck.',array['https://en.wikipedia.org/wiki/X_Games','https://snowboardmag.com/stories/history-winter-x-games-part-1','https://www.aspendailynews.com/winter-x-games-a-brief-history/article_3459d151-30c8-5345-a0a9-2837bdfe8211.html','https://www.xgames.com/past-events/']::text[],'verified')
