insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('winter-x-games-europe','Winter X Games Europe',array['X Games Tignes']::text[],'major-contest','ESPN',2010,2013,'defunct','Tignes','France','europe',array['superpipe','slopestyle']::text[],'First X Games competition held outside the United States. Run at Tignes, France for four editions (2010-2013), then cut when ESPN scaled back its international X Games expansion.',array['https://en.wikipedia.org/wiki/Winter_X_Games_Europe','https://www.downdays.eu/events/behind-the-scenes/a-brief-history-of-the-x-games-in-europe/','https://en.wikipedia.org/wiki/Winter_X_Games_XVII']::text[],'verified')
