insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('winter-youth-olympic-snowboarding','Snowboarding at the Winter Youth Olympic Games','{}'::text[],'major-contest','IOC (sport governed at the Games by FIS)',2012,null,'active',null,'multiple','global',array['halfpipe','slopestyle','boardercross','big-air','team']::text[],'Snowboarding has been on the programme since the first Winter Youth Olympic Games at Innsbruck in 2012 (halfpipe and slopestyle only), growing to nine events at Gangwon 2024. RESULTS ARCHIVE for a later pass: Olympedia per-Games event index at https://www.olympedia.org/editions/70/sports/SBD (Lausanne 2020) and https://www.olympedia.org/editions/73/sports/SBD (Gangwon 2024); 2012 and 2016 Olympedia edition ids not yet located - see open_questions.',array['http://www.olympedia.org/definitions/70','https://www.olympedia.org/editions/70/sports/SBD','https://www.olympedia.org/editions/73/sports/SBD']::text[],'verified')
