insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('world-rookie-finals','World Rookie Finals',array['Völkl World Rookie Finals','World Rookie Snowboard Finals']::text[],'major-contest','World Snowboard Federation / Black Yeti',null,null,'active',null,'multiple','europe',array['slopestyle','halfpipe','big-air']::text[],'Season-closing event of the World Rookie Tour, held in an Alpine resort in spring, where the World Rookie Champion titles are awarded in the Rookie and Grom divisions. It carried a 3Star TTR rating in 2015. Host resorts have included Ischgl (2015) and Kitzsteinhorn (2025).',array['https://www.worldrookietour.com/the-tour/','https://www.worldsnowboardfederation.org/world-rookie-snowboard-finals-2025-2/','https://www.worldsnowboardfederation.org/2017-world-rookie-finals-kitzsteinhorn-kaprun/','https://www.worldsnowboardfederation.org/?s=Ischgl']::text[],'likely')
