insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('world-rookie-tour','World Rookie Tour','{}'::text[],'tour-series','World Snowboard Federation / Black Yeti',null,null,'active',null,'multiple','global',array['slopestyle','halfpipe','big-air','rail-jam']::text[],'Global youth freestyle tour organised by the World Snowboard Federation with national snowboard associations, feeding the World Rookie Ranking. Age divisions are Rookie (U18), Grom (U15) and Supergrom (U13); the ranking averages an athlete''s three best results from Level 1-3 Star WSPL events. Stops are branded ''Rookie Fests'' and are spread across Europe, South America, Australia and Japan, with the season closing at the World Rookie Finals. The Livigno World Rookie Fest, the tour''s anchor stop, was in its 19th edition in 2024, which implies a first edition around 2006.',array['https://www.worldsnowboardfederation.org/wsf-projects/world-rookie-tour/','https://www.worldrookietour.com/the-tour/','https://www.worldsnowboardfederation.org/the-new-snowboard-generation-shines-at-livigno-world-rookie-fest-2024/']::text[],'likely')
