insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('world-ski-snowboard-festival','World Ski & Snowboard Festival',array['TELUS World Ski & Snowboard Festival','TWSSF']::text[],'major-contest','independent',1996,null,'active','Whistler Blackcomb','Canada','north-america',array['big-air','slopestyle','halfpipe','rail-jam','freeride','other']::text[],'Ten-day (later shortened) April festival in Whistler founded by Doug Perry in 1996, growing out of the 1994 World Technical Skiing Championships on Blackcomb. It absorbed the existing spring contests including the WestBeach Classic, the Whistler Cup and the Couloir Extreme, and became the umbrella under which most of Whistler''s spring snowboard contests ran. A 2006 economic impact assessment put its activity at $37.7 million for British Columbia; 2007 attendance was reported at 275,000. Vail Resorts shortened the format after 2018; Gibbons Whistler took full ownership in November 2019.',array['https://whistlermuseum.org/2024/04/09/wssf-the-beginning/','https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival','http://www.watermarkinc.ca/twssfmedia/timecapsule/backgrounder.html','https://wssf.com/','https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx']::text[],'verified')
