insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('world-snowboarding-championship-whistler','World Snowboarding Championship (Whistler)','{}'::text[],'major-contest','independent',2001,null,'unconfirmed','Whistler Blackcomb','Canada','north-america',array['superpipe','slopestyle','jib']::text[],'Independent Whistler championship produced by The Masters Group and backed by WestBeach Sports, which redirected its WestBeach Classic budget into it for 2001. Contested slopestyle, jib jam and superpipe over 19-22 April 2001. Distinct from the FIS Snowboarding World Championships. How many years it ran could not be established.',array['https://www.piquenewsmagazine.com/local-sports/westbeach-classic-not-on-2459602','https://www.piquenewsmagazine.com/local-sports/whistler-the-year-in-sports-2461092']::text[],'likely')
