insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('world-snowboarding-championships','World Snowboarding Championships',array['TTR World Snowboarding Championships','The World Championships of Snowboarding']::text[],'major-contest','TTR / World Snowboard Federation',2012,null,'unconfirmed',null,'multiple','global',array['halfpipe','slopestyle']::text[],'Rider-side world championship developed and owned by TTR and the World Snowboard Federation, approved by unanimous vote at the TTR and WSF general assemblies in Barcelona in May 2010. The first edition, in Oslo in February 2012, was described as the first championships run by snowboarders since 1999; the 2011 Oakley Arctic Challenge was staged as its trial event. The local organising company Snowboard-VM 2012 AS was owned by The Arctic Challenge, the Norwegian Snowboard Federation and Oslo Vinterpark.',array['https://en.wikipedia.org/wiki/2012_World_Snowboarding_Championships','https://www.worldsnowboardfederation.org/the-oakley-arctic-challenge-announces-2011-rider-protocol/','https://www.worldsnowboardfederation.org/ttr-world-snowboarding-championships-2012-highlights/','https://www.worldsnowboardfederation.org/the-world-championships-of-snowboarding-2016-2/']::text[],'verified')
