insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('world-snowboarding-championships-sims','World Snowboarding Championships',array['Sims World Snowboarding Championships','Swatch World Championships']::text[],'legacy-contest','brand-run',1983,null,'defunct',null,'USA','north-america',array['halfpipe','slalom','giant-slalom','downhill','mogul','other']::text[],'Founded by Tom Sims at Soda Springs, California, and the first snowboard contest to include a halfpipe. Sims registered the service mark WORLD SNOWBOARDING CHAMPIONSHIPS with the USPTO (reg. 1530152, filed 8 July 1987) claiming first use in commerce on 15 February 1983. The event moved to Breckenridge, Colorado for 1986 and 1987 and picked up Swatch as title sponsor; a rival European edition ran at Livigno and St Moritz in January 1987.',array['https://trademarks.justia.com/736/70/world-snowboarding-championships-73670866.html','https://www.snowboarder.com/transworld-snowboarding-archive/a-complete-history-of-the-snowboard-halfpipe','https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/sports/soda-springs-goes-retro-for-tom-sims/','https://www.skihall.com/hall-of-famers/tom-sims/','https://snowbrains.com/snowboarding-pioneer-paul-alden-dies-aged-89/','https://snowbrains.com/breckenridge-resort-co-marks-40-years-of-snowboarding-history-with-new-worlds-competition/']::text[],'likely')
