insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('wsf-south-america-tour','WSF South America Tour','{}'::text[],'tour-series','WSF (World Snowboard Federation)',null,null,'unconfirmed',null,'multiple','south-america',array['slopestyle','big-air','rail-jam']::text[],'Southern-hemisphere winter circuit that gave South American riders TTR and WSF ranking points, running from an urban rail jam in Santiago through Valle Nevado and El Colorado to an indoor finale in Rio de Janeiro.',array['https://www.worldsnowboardfederation.org/winter-season-in-chile/']::text[],'verified')
