insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('x-games-norway','X Games Norway',array['X Games Oslo']::text[],'major-contest','ESPN',2016,2020,'defunct',null,'Norway','europe',array['superpipe','slopestyle','big-air','other']::text[],'ESPN''s Norwegian X Games, launched in Oslo in 2016 as the first X Games to stage summer and winter disciplines in one city. Alternated between Oslo (2016, 2018, 2019) and Hafjell (2017, 2020). The 2018 and 2019 Oslo editions were indoor big air held at Telenor Arena, Fornebu, in May and August respectively.',array['http://www.labelnetworks.com/x-games-oslo-to-launch-in-february-2016-bringing-together-both-summer-and-winter-sports/','https://www.firsttracksonline.com/2015/11/09/x-games-expands-to-oslo/','https://de.wikipedia.org/wiki/X-Games_Norway_2017','https://www.hafjellresort.no/en/x-games','https://radseason.com/event/x-games-norway-fornebu-norway/','https://en.wikipedia.org/wiki/X_Games']::text[],'verified')
