insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('x-trail-jam','Nissan X-Trail Jam',array['X-Trail Jam in Tokyo Dome']::text[],'major-contest','TTR',2001,null,'defunct','Tokyo Dome','Japan','japan',array['quarterpipe','big-air']::text[],'Indoor stadium contest launched in the Tokyo Dome in 2001, running a quarterpipe and a straight-jump (big air) event on real snow trucked into the baseball stadium. Reto Lamm - the first Air & Style winner and later TTR Pro Snowboarding president - is credited as president and main developer. It became a TTR 6Star event.',array['https://en.wikipedia.org/wiki/X-Trail_Jam','https://www.methodmag.com/industry-news/ttr-world-snowboard-tour-6-star-event-nissan-xt.html','https://snowboardnet.jp/x-trail-jam-in-tokyo-dome-3/','https://backside.jp/news-1101/']::text[],'likely')
