insert into public.event_series (series_id,series_name,former_names,category,governing_body,first_year,last_year,status,home_venue,country,region,disciplines,significance,sources,confidence) values ('zillertal-valley-ralley','Zillertal Vaelley Raelley','{}'::text[],'tour-series','independent (Blue Tomato / Zillertal Tourismus / Die Aesthetiker)',2013,null,'active',null,'Austria','europe',array['slopestyle']::text[],'Zillertal-based slopestyle tour hosted by Blue Tomato with Zillertal Tourismus and the Aesthetiker snowboard club, feeding the World Snowboard Points List and the World Rookie Ranking. 2025/26 is its 13th season, which places the first season at 2013/14. Its Mayrhofen stop runs in the PenkenPark.',array['https://www.worldsnowboardfederation.org/zillertal-valley-ralley-announces-new-tour-dates-for-2025-2026/']::text[],'likely')
