insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('air-and-style--1994-a','air-and-style',1994,'1st Red Bull Air & Style','1994-01-17','1994-01-17','day','Bergisel Stadium','Innsbruck','Austria',array['big-air']::text[],'held',null,'Inaugural edition, a single straight jump with a USD 10,000 purse. Organisers expected about 100 spectators and over a thousand came. Some sources (World Snowboard Federation, Collective) date the event''s founding to 1993; the contest itself is dated 17 January 1994 by Wikipedia and Austria-Forum.',array['https://en.wikipedia.org/wiki/Air_%26_Style','https://whitelines.com/events/air-style-innsbruck','https://austria-forum.org/af/AustriaWiki/Air_&_Style']::text[],'verified')
