insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('air-and-style--1999','air-and-style',1999,'7th G-Shock Air & Style','1999-12-04','1999-12-04','day','Bergisel Stadium','Innsbruck','Austria',array['big-air']::text[],'held',null,'Over 45,000 spectators. A crowd crush as the venue emptied after the show killed five people; a sixth, one of five badly injured teenagers, died four years later of the consequences. A court found that Tyrol and the city of Innsbruck should have cancelled the event because the venue was unsafe. Innsbruck refused permission for further events and the contest moved to Seefeld.',array['https://en.wikipedia.org/wiki/Air_%26_Style','https://austria-forum.org/af/AustriaWiki/Air_&_Style']::text[],'verified')
