insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('air-and-style--2016-a','air-and-style',2016,'Opel Air + Style Innsbruck 2016',null,null,null,'Olympiaworld Innsbruck','Innsbruck','Austria',array['big-air']::text[],'held',null,'First year at Olympiaworld rather than in the Bergisel stadium (Onboard''s report places the arena in an open car park beside the Bergisel). Strong valley winds forced organisers to cancel the rounds after round two and to score the podium from the three highest combined round-two scores. Collective reports 2016 as the first year women competed at Innsbruck; Method Mag says the first women''s field at Innsbruck was 2017. Shaun White announced during the event that the tour would expand to five stops. Exact dates not found in a source I opened.',array['https://www.innsbruck.info/blog/en/events/air-and-style2016/','https://onboardmag.com/news/snowboarding-events/bad-wind-airs-tyle-innsbruck-2016-report-gallery.html','https://collectivemag.de/air-style-vom-bergisel-stadion-in-die-ganze-welt-pid16548/']::text[],'likely')
