insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('air-and-style--2017-a','air-and-style',2017,'Air + Style Innsbruck-Tirol 2017','2017-02-01',null,'month','Olympiaworld Innsbruck','Innsbruck','Austria',array['big-air']::text[],'held',null,'Method Mag calls this the 34th edition and says it was the first year women competed in the Air + Style big air, with 30 men and 8 women plus 16 live music acts over two days. Tiroler Tageszeitung reports the Air+Style contest''s history ended in 2017 in the Olympiaworld car park. Edition numbering here (34th) is inconsistent with Wikipedia''s numbering (25th for Beijing 2013).',array['https://www.methodmag.com/news/air-style-festival-innsbruck-tirol-2017.html','https://www.tt.com/artikel/16237751/das-erbe-des-air-style-snowboarder-fliegen-wieder-auf-bergisel-ab']::text[],'likely')
