insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('burton-canadian-open--2009','burton-canadian-open',2009,'2009 Burton Canadian Open',null,null,null,'Canada Olympic Park','Calgary','Canada',array['slopestyle']::text[],'held',null,'Rated Swatch TTR 5Star. Mikkel Bang and Silvia Mittermueller won the slopestyle, reported by Onboard on 2009-02-09. Unresolved: the 2008/09 Burton Global Open Series calendar announced the Burton Canadian Open for 2008-12-01 to 2008-12-07 at the same venue, so either the edition moved to February 2009 or there were two runnings. Only one edition row is recorded here.',array['https://onboardmag.com/news/snowboarding-events/burton-canadian-open-slopestyle.html','https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[],'likely')
