insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('burton-european-open--1999','burton-european-open',1999,'1999 Burton European Open',null,null,null,'Axamer Lizum / Seegrube','Innsbruck','Austria',array['halfpipe','slopestyle']::text[],'held',null,'Reported as the first Burton European Open, with the halfpipe at Axamer Lizum and the slopestyle at Seegrube in the Innsbruck area. Natasza Zurek won the halfpipe. Note that later edition numbering used by the organisers and the World Snowboard Federation (2011 = 12th annual, 2012 = 13th annual) counts the first edition as 2000, so the year of this first edition is disputed.',array['https://www.burton.com/blogs/the-burton-blog/10-years-laax-open/','https://coolerlifestyle.com/news/events/burton-european-open-looks-back-at-ten-years-of-epic-snowboarding.html']::text[],'likely')
