insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('burton-european-open--2008','burton-european-open',2008,'2008 Burton European Open','2008-01-11','2008-01-18','day','Laax','Laax','Switzerland',array['halfpipe','slopestyle']::text[],'held',null,'The fourth 6Star stop of the Swatch TTR World Snowboard Tour season and the first event that season to host both men''s and women''s fields, with 1000 ranking points per discipline.',array['https://www.worldsnowboardfederation.org/burton-european-open-2008/','https://www.worldsnowboardfederation.org/burton-european-open-08-results/']::text[],'verified')
