insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('burton-global-open-series--2008','burton-global-open-series',2008,'2008/09 Burton Global Open Series','2008-07-29','2009-03-22','day',null,null,'multiple',array['halfpipe','slopestyle']::text[],'held',null,'Six-stop season, announced as: Burton New Zealand Open, Snow Park NZ, 2008-07-29 to 2008-08-02; Burton Australian Open, Perisher Blue, 2008-09-02 to 2008-09-06; Burton Canadian Open, Canada Olympic Park, 2008-12-01 to 2008-12-07; Burton European Open, Laax, 2009-01-09 to 2009-01-16; Nissan X-Trail Nippon Open, ALTS Bandai, 2009-02-24 to 2009-03-01; Burton US Open, Stratton Mountain, 2009-03-16 to 2009-03-22. Year recorded as 2008, the calendar year the season opened; end date is the announced close of the US Open.',array['https://whitelines.com/archive/news/burton-global-open-series-08-09.html']::text[],'verified')
