insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('hot-dawgz-and-hand-rails--2013','hot-dawgz-and-hand-rails',2013,'10th Anniversary Hot Dawgz & Hand Rails','2013-09-22',null,'day','Bear Mountain','Big Bear Lake, California','USA',array['rail-jam','jib']::text[],'held',null,'Men''s winner Tommy Gesme took a $10,000 first prize; Dillon Ojo 2nd, Jordan Small 3rd. Melissa Evans won the women''s event, described as her fourth win at the contest. Jaeger Bailey took Best Trick. Not in the wave 1 edition list; results not recorded here because edition_ids must come from the input file.',array['https://www.snowboarder.com/news/tommy-gesme-wins-hot-dawgz-hand-rails-2013']::text[],'verified')
