insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('isf-world-championships--1993','isf-world-championships',1993,'1993 ISF Snowboard World Championships','1993-01-01','1993-01-01','month',null,'Ischgl','Austria',array['halfpipe','giant-slalom','slalom','other']::text[],'held',null,'First ISF world championships. Snowboarder/TransWorld 1990s timeline gives January 1993 at Ischgl, Austria and says Kevin Delaney and Michele Taggart won the combined titles; carvers.it repeats the same. German Wikipedia lists slalom, combined, halfpipe and giant slalom as the 1993 disciplines. Only the combined winners are recorded; no full podium found.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s','https://www.carvers.it/storia-inglese/','https://de.wikipedia.org/wiki/Snowboard-Weltmeisterschaft']::text[],'likely')
