insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('isf-world-snowboarding-championships--2000','isf-world-snowboarding-championships',2000,'Motorola ISF World Championships 1999/2000 - halfpipe final','2000-04-08','2000-04-08','day','Jakobshorn, Davos','Davos','Switzerland',array['halfpipe']::text[],'held',null,'Halfpipe world championship decider of the season-long Motorola ISF World Pro Tour, run in front of roughly 5,000 spectators, with alpine finals alongside. The tour then moved to Laax for the boardercross. Records the title as decided over a season rather than at a single championship meeting.',array['https://www.sportcal.com/pressreleases/the-motorola-isf-world-championships-1999-2000-halfpipe-davos-sui/']::text[],'verified')
