insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('kaunertal-opening--2015','kaunertal-opening',2015,'30th Kaunertal Opening',null,null,null,'Snowpark Kaunertal','Kaunertal','Austria',array['jib','other']::text[],'held',null,'30th anniversary edition, run over three bluebird days on the glacier at 3,000m with the park spread across four locations. Separate pro contest categories for men and women, a Legends Invitational session, the Mega Testival, a Jib''n''Skate Jam and the KTO Music Festival. The mini-ramp returned after a 15-year absence. Sources give no exact competition dates; the World Snowboard Guide page is dated 13 October 2015.',array['https://onboardmag.com/news/snowboarding-events/30th-kaunertal-opening-event-recap.html','https://www.worldsnowboardguide.com/news/30th-kaunertal-opening-2015.html']::text[],'likely')
