insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('kaunertal-opening--2022','kaunertal-opening',2022,'37th Kaunertal Opening (KTO 2022)','2022-10-15','2022-11-20','day','Snowpark Kaunertal, Kaunertal Glacier','Kaunertal','Austria',array['jib','other']::text[],'held','Ran as two separate weekends, 15-16 October and 19-20 November 2022; the date range is not continuous.','New two-weekend format: the Jib''n''Playground Edition on 15-16 October and the Testival Open & Snowpark Days on 19-20 November. Cash-for-tricks sessions across several categories plus snowskate competitions and a multi-brand park testival. Powered by Monster Energy. [QA-flagged: non-continuous dates.]',array['https://whitelines.com/snowboard-culture/snowboard-events/kto-2022-kaunertal-opening-is-back.html']::text[],'verified')
