insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('mt-baker-legendary-banked-slalom--2015','mt-baker-legendary-banked-slalom',2015,'2015 Legendary Banked Slalom',null,null,null,'Mt. Baker Ski Area','Deming, Washington','USA',array['banked-slalom']::text[],'cancelled','The 30th Legendary Banked Slalom, scheduled for 2015, was postponed to 18-21 February 2016 for lack of snow. The organisers announced a scaled-down two-day substitute, the "29½ Banked Slalom", for 21-22 March 2015, and then cancelled that too in a 18 March update.','Intended as the 30th Legendary Banked Slalom. The 30th ran instead in February 2016. A substitute "29½ Banked Slalom" (one Saturday qualifying run, two Sunday finals runs) was announced for 21-22 March 2015 and cancelled on 18 March 2015.',array['https://www.mountbakerexperience.com/stories/30-years-of-the-legendary-banked-slalom,339','http://www.cascadiadaily.com/2024/feb/01/mt-baker-ski-area-cancels-annual-slalom-race/','https://en.wikipedia.org/wiki/Mt._Baker_Legendary_Banked_Slalom','https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20150302043807/http://lbs.mtbaker.us/','https://web.archive.org/web/20150510124822/http://lbs.mtbaker.us/']::text[],'verified')
