insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('mt-baker-legendary-banked-slalom--2024','mt-baker-legendary-banked-slalom',2024,'2024 Legendary Banked Slalom','2024-02-09','2024-02-11','day','Mt. Baker Ski Area','Deming, Washington','USA',array['banked-slalom']::text[],'cancelled','Scheduled as the 36th Legendary Banked Slalom for 9-10-11 February 2024, then re-scheduled to February 2025.','Scheduled as the 36th Legendary Banked Slalom for February 9-11, 2024. Mt. Baker CEO Gwyn Howat: ''El Nino has now washed the 36th Legendary Banked Slalom into 2025.'' The 36th was then run in February 2025. [v0.3 archive: IMPORTANT CORRECTION: the catalog currently lists 2024 as held with dates 2024-02-09/11. The 36th LBS was indeed scheduled for February 9-10-11, 2024 (homepage, 30 Jan 2024) but by 21 March 2024 the homepage read "36th Legendary Banked Slalom Re-scheduled to February 2025". The 2024 event did not run.]',array['http://www.cascadiadaily.com/2024/feb/01/mt-baker-ski-area-cancels-annual-slalom-race/','https://localfreshies.com/mt-baker-cancelled-2024/','https://lbs.mtbaker.us/results/honor-roll/','https://web.archive.org/web/20240130155523/https://lbs.mtbaker.us/','https://web.archive.org/web/20240321202806/https://lbs.mtbaker.us/']::text[],'verified')
