insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('mt-baker-legendary-banked-slalom--2025','mt-baker-legendary-banked-slalom',2025,'36th Legendary Banked Slalom','2025-02-07','2025-02-09','day','Mt. Baker Ski Area','Deming, Washington','USA',array['banked-slalom']::text[],'held',null,'Held as the 36th edition, a year after the 36th was washed out in 2024. A cold storm the weekend before and more snow the Wednesday before the race left good conditions. Registration capped at 400. Mt. Baker CEO Gwyn Howat has set the course for over 30 years.',array['http://www.cascadiadaily.com/2025/feb/04/mt-baker-ski-area-prepares-for-world-famous-snowboard-race/','https://slushthemagazine.com/blogs/features/2025-mt-baker-legendary-banked-slalom-recap-photos','https://lbs.mtbaker.us/results/honor-roll/','https://lbs.mtbaker.us/results/']::text[],'verified')
