insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('mt-baker-legendary-banked-slalom--2026','mt-baker-legendary-banked-slalom',2026,'2026 Legendary Banked Slalom','2026-02-06','2026-02-08','day','Mt. Baker Ski Area','Deming, Washington','USA',array['banked-slalom']::text[],'cancelled','Scheduled as the 37th Legendary Banked Slalom for 6-7-8 February 2026, then postponed to 19-21 February 2027.','Scheduled as the 37th Legendary Banked Slalom for February 6-8, 2026. Racers registered for 2026 remain eligible for the rescheduled 2027 event, which was moved later in February to allow more snow to build. [v0.3 archive: IMPORTANT CORRECTION: the catalog lists 2026 with dates 2026-02-06/08. The 37th LBS was scheduled for February 6-7-8, 2026 (homepage, 17 Dec 2025); by 22 January 2026 the homepage banner read "37th LBS • Feb. 19-20-21, 2027 • postponement announcement" and it still read that in the most recent capture (June 2026). The 2026 event did not run.]',array['http://www.cascadiadaily.com/2026/jan/22/mt-bakers-legendary-banked-slalom-canceled-due-to-unworkable-conditions/','https://lbs.mtbaker.us/37th-2027/','https://localfreshies.com/banked-slalom-event-showcase/','https://web.archive.org/web/20251217181004/https://lbs.mtbaker.us/','https://web.archive.org/web/20260122212354/https://lbs.mtbaker.us/']::text[],'verified')
