insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('national-snurfing-championships--1979','national-snurfing-championships',1979,'1979 National Snurfing Championships',null,null,null,'Blockhouse Hill, Muskegon State Park','Muskegon','USA',array['other']::text[],'held',null,'Michigan Snowboard Museum gives Blockhouse Hill as the venue and calls 1979 the final year there. Wikipedia''s snowboarding article places the 1979 National Snurfing Championship at Muskegon State Park; other secondary accounts place a 1979 ''World Snurfing Championship'' at Pando near Grand Rapids. Jake Burton Carpenter entered with his own bindinged board and a separate open/modified division was created for him.',array['https://www.michigansnowboardmuseum.com/michigan-snowboarding-history-timeline.html','https://en.wikipedia.org/wiki/Snowboarding']::text[],'likely')
