insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('neil-edgeworth-memorial-banked-slalom--2017','neil-edgeworth-memorial-banked-slalom',2017,'20th Annual Neil Edgeworth Memorial Banked Slalom','2017-03-25','2017-03-26','day','Big White Ski Resort','Kelowna','Canada',array['banked-slalom']::text[],'held',null,'Record field of 320 riders aged 6 to 63, on the natural gully beside the Ridge Rocket chair. $5,000 split among the pro winners plus $10,000 across the other categories. Stephanie Haines became the first rider to win the female pro category four years running.',array['https://www.bigwhite.com/explore-big-white/blog/telus-park/big-white-hosts-20th-annual-neil-edgeworth-banked-slalom']::text[],'verified')
