insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('nippon-open--2008','nippon-open',2008,'2008 Nissan X-Trail Nippon Open','2008-02-26','2008-03-02','day','ALTS Bandai','Bandai, Fukushima','Japan',array['halfpipe','slopestyle']::text[],'held',null,'5Star event on the TTR tour, reported as drawing over 40,000 spectators. The parkstyle finals ran after heavy snow and high winds earlier in the week, with semi-finals and finals held back to back; Mikkel Bang and Jenny Jones won. Winners took 8,000 points toward the Burton Global Open Series championship.',array['https://whitelines.com/archive/news/japan-beckons-riders-for-5-star-nissan-x-trail-nippon-open.html','https://whitelines.com/archive/news/mikkel-bang-jenny-jones-win-nissan-x-trail-nippon-open-parkstyle-finals.html']::text[],'verified')
