insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('shakedown-snowboard-games--2015','shakedown-snowboard-games',2015,'2015 Shakedown','2015-04-04','2015-04-04','day','Mont Saint-Sauveur','Saint-Sauveur','Canada',array['slopestyle','big-air','jib']::text[],'held',null,'Last edition listed by the event''s own edition table. SnowboardQuebec''s timeline places a cancelled Shakedown season in its 2015 entry, and CBC reported a Shakedown cancellation in January 2016 for lack of sponsorship and snow; whether the 2015 contest ran and the 2016 one was cancelled is unresolved - see open questions.',array['https://en.wikipedia.org/wiki/Shakedown_(Snowboard_Games)','https://www.snowboardquebec.com/histoire/']::text[],'likely')
