insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('showcase-showdown--1997','showcase-showdown',1997,'1997 Showcase Showdown (first edition)','1997-02-01','1997-02-01','day','Blackcomb Mountain','Whistler','Canada','{}'::text[],'held',null,'Whistler Blackcomb''s 60th anniversary timeline dates the first Showcase Showdown to 1 February 1997. Snowboard Magazine''s billing of the 2015 event as the 18th annual implies a 1998 start instead; the discrepancy is unresolved. The Whistler Museum separately records a Showcase Snowboards halfpipe competition on Blackcomb in 1992, won in the male 18-plus category by Whistler''s Robin Dow, which may be a predecessor.',array['https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx','https://whistlermuseum.org/2022/04/05/snowboard-park-no-skiers-allowed/']::text[],'likely')
