insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('showcase-showdown--2015','showcase-showdown',2015,'18th annual Showcase Showdown','2015-03-14','2015-03-15','day','Nintendo Terrain Park, Blackcomb Mountain','Whistler','Canada',array['big-air','rail-jam']::text[],'held',null,'Big air with a junior rail jam added for the first time. $22,000 in total prizes; $10,000 to the pro men''s winner plus a start in the WSSF Monster Energy Shred Show. Presented by Monster Energy, Burton and Vans, with an after-party featuring Anti-Flag. Snowboard Magazine lists the contest date as Saturday 14 March; the Georgia Straight gives 14-15 March.',array['https://snowboardmag.com/news/whistler-blackcombs-18th-annual-showcase-showdown-returns-march-14','https://www.straight.com/life/402596/showcase-showdown-and-whistler-ski-and-snowboard-fest-go-far-beyond-rock-n-snow']::text[],'verified')
