insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snoboard-shop-north-american-championships--1985','snoboard-shop-north-american-championships',1985,'1985 Snoboard Shop North American Snowboarding Championships (first edition)',null,null,null,null,null,'Canada',array['other']::text[],'held',null,'SnowboardQuebec''s history page states Ken Achenbach''s Snoboard Shop launched the North American Snowboarding Championships in Alberta in 1985 with a $20,000 purse, calling it the first snowboard event held in Canada, and says the series ended in 1988. Venue for 1985 is unconfirmed: the 1987 edition is sourced to Sunshine Village and later accounts describe an annual May long weekend contest there, but the one source naming a 1985 result places the event ''in Calgary''.',array['https://www.snowboardquebec.com/histoire/','https://snowboarding8090.com/history/','https://kootenaymountainculture.com/meet-the-men-who-brought-snowboarding-to-canada/']::text[],'likely')
