insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snoboard-shop-north-american-championships--1987','snoboard-shop-north-american-championships',1987,'1987 Snoboard Shop North American Championships','1987-05-01','1987-05-01','month','Sunshine Village','Banff','Canada',array['other']::text[],'held',null,'Held on the May long weekend with a $20,000 purse. A photograph of Dave Achenbach from this event ran on the cover of the first issue of TransWorld Snowboarding. Exact dates and the disciplines run were not sourced.',array['https://kootenaymountainculture.com/meet-the-men-who-brought-snowboarding-to-canada/']::text[],'likely')
