insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snoboard-shop-north-american-championships--1988','snoboard-shop-north-american-championships',1988,'1988 Snoboard Shop North American Snowboarding Championships',null,null,null,'Mt Norquay','Banff','Canada',array['other']::text[],'held','Venue changed: Sunshine Village withdrew from hosting mid-season and Mt Norquay took the event on.','Norquay''s own history says hosting the event put the resort on the cover of TransWorld Snowboarding. SnowboardQuebec''s history records 1988 as the final year of the series.',array['https://banffnorquay.com/blog/lift-lines-humans-of-norquay-a-hill-makes-space-for-snowboarding/','https://www.snowboardquebec.com/histoire/']::text[],'likely')
