insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snowboard-jamboree--2013','snowboard-jamboree',2013,'2013 Snowboard Jamboree / FIS Snowboarding World Championships','2013-01-18','2013-01-27','day','Stoneham Mountain Resort','Stoneham-et-Tewkesbury','Canada',array['big-air','halfpipe','slopestyle','boardercross','parallel-giant-slalom','parallel-slalom']::text[],'held',null,'The 2013 FIS Snowboarding World Championships were staged at Stoneham on these dates. Ski Canada''s 2014 preview describes the 2014 Jamboree as the 9th edition, which places the 2013 festival as the 8th.',array['https://en.wikipedia.org/wiki/FIS_Snowboarding_World_Championships_2013','https://www.skicanada.org/snowboard-world-cup-returns-stoneham-quebec-city/']::text[],'likely')
