insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snowboard-jamboree--2014','snowboard-jamboree',2014,'9th Snowboard Jamboree','2014-01-16','2014-01-19','day','Stoneham Mountain Resort and Quebec City','Quebec City','Canada',array['big-air','slopestyle','halfpipe']::text[],'held',null,'Billed as the 9th Snowboard Jamboree and the 15th World Cup held in Quebec. First year the event was sanctioned as a 5-star World Snowboard Tour stop and first year it offered three freestyle World Cup disciplines. Last international snowboard competition before the Sochi 2014 Olympics. Stairsmasters video contest returned.',array['https://www.skicanada.org/snowboard-world-cup-returns-stoneham-quebec-city/','https://www.skicanada.org/stoneham-snowboard-jamboree-now-world-cup-event/']::text[],'verified')
