insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snowboard-jamboree--2015','snowboard-jamboree',2015,'10th Snowboard Jamboree','2015-02-19','2015-02-22','day','Stoneham Mountain Resort and Ilot Fleurie, Quebec City','Quebec City','Canada',array['big-air','slopestyle']::text[],'held','The halfpipe World Cup scheduled for 22 February at Stoneham was cancelled: organisers cited a significant lack of snow, warm weather and a labour dispute making an FIS-standard pipe impossible.','10th edition and the 16th FIS Snowboard World Cup held at the festival. Big air on 20 February at Ilot Fleurie in downtown Quebec City, slopestyle on 21 February at Stoneham. About 200 athletes from more than 20 countries. First time 19 women contested big air at a World Cup here. Stairsmasters video contest ran alongside.',array['https://snowboardmag.com/news/quebec-city-snowboard-jamboree-festival-back-for-10th-edition','https://www.snowboardquebec.com/2014/snowboard-jamboree/']::text[],'verified')
