insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('snowboard-jamboree--2016','snowboard-jamboree',2016,'2016 Snowboard Jamboree','2016-02-12','2016-02-14','day','Ilot Fleurie','Quebec City','Canada',array['big-air']::text[],'held',null,'Moved entirely into downtown Quebec City and cut back to a single big air World Cup, carrying both FIS and TTR World Snowboard Tour points. Maxence Parrot worked on the venue build. Programme also included the Stairsmasters video contest and the IF3 film festival. Organisers described 16 years of World Cup racing in the region and seven consecutive World Cups in Quebec City from 2009.',array['https://www.firsttracksonline.com/2015/10/01/quebecs-world-cup-jamboree-goes-urban/']::text[],'verified')
