insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('spring-battle--2025','spring-battle',2025,'Spring Battle 2025','2025-03-08','2025-03-12','day','Absolut Park','Flachauwinkl','Austria',array['slopestyle','rail-jam']::text[],'held',null,'WSF Elite Level Event counting for the World Snowboard Points List, EUR 65,000 prize purse. Riders had several days to film single-take runs with follow-cam filmers (no editing permitted), judged afterwards by an international WSF panel. Snowboard slopestyle on the Absolut Park kicker line; Best Trick Rail open to snowboarders and freeskiers in a dedicated jib park. Award ceremony 14 March at Haus Flachau.',array['https://www.absolutpark.com/en/spring-battle-25/']::text[],'verified')
