insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2003','ttr-world-snowboard-tour',2003,'2002/03 TTR Pro Snowboarding Series season',null,null,null,null,null,'multiple','{}'::text[],'held',null,'First TTR season: nine events worldwide with the Arctic Challenge as the final stop, each event awarding one TTR Medallion and an Arctic Challenge invite. No women''s tour until 2005/06. Events: Nissan X-Trail Jam, Nokia Air & Style, O''Neill SB Jam, Burton European Open, Champs Open, Vans Triple Crown of Snowboarding, The Battle, Quiksilver Slopestyle Pro, US Open.',array['https://web.archive.org/web/20220302222719/https://worldsnowboardtour.com/history/']::text[],'verified')
