insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2005','ttr-world-snowboard-tour',2005,'2004/05 TTR World Snowboard Tour season',null,null,null,null,null,'multiple',array['halfpipe','slopestyle','big-air','quarterpipe']::text[],'held',null,'Season edition rows use the calendar year the season ended. The Arctic Challenge''s own 2005 site published the 2004/2005 TTR Tour standings, with Andy Finch as overall champion, which confirms the season ran.',array['https://www.the-arctic-challenge.com/']::text[],'likely')
