insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2006','ttr-world-snowboard-tour',2006,'2005/06 TTR World Snowboard Tour season',null,null,null,null,null,'multiple','{}'::text[],'held',null,'Introduction of the 1-6Star tier system, the TTR ranking system, the first TTR website (ttrworldtour.com) and the official Women''s Tour. 67 events in total. The TTR World Ranking list launched 5 December 2005 and the first-ever TTR World Tour Champions were crowned at the US Open.',array['https://web.archive.org/web/20220302222719/https://worldsnowboardtour.com/history/']::text[],'verified')
