insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2007','ttr-world-snowboard-tour',2007,'2006/07 TTR World Snowboard Tour season',null,null,null,null,null,'multiple',array['halfpipe','slopestyle','big-air','quarterpipe']::text[],'held',null,'First season with a dedicated women''s tour, announced 24 October 2006. WSF described a provisional women''s calendar of over 20 events offering more than 30 possible results, kicking off with the Burton Abominable Snow Jam at Mt Hood in July 2006 and ending at the Roxy Chicken Jam Finals in Park City, 22-25 March 2007. The Billabong Pro Junior in Australia and the Burton Australian Open were cancelled for poor snow.',array['https://www.worldsnowboardfederation.org/ttr-women-tour-announced/']::text[],'verified')
