insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2008','ttr-world-snowboard-tour',2008,'2007/08 Swatch TTR World Snowboard Tour season',null,null,null,null,null,'multiple','{}'::text[],'held',null,'Introduction of a $250,000 end-of-season prize purse. 176 results registered across four formats from events in 27 nations; 3,417 riders (2,706 men, 711 women) from 41 nations ranked.',array['https://web.archive.org/web/20220302222719/https://worldsnowboardtour.com/history/']::text[],'verified')
