insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2010','ttr-world-snowboard-tour',2010,'2009/10 Swatch TTR World Snowboard Tour season',null,null,null,null,null,'multiple',array['halfpipe','slopestyle','big-air','quarterpipe']::text[],'held',null,'Second of Peetu Piiroinen''s three consecutive men''s overall titles; WSF reported he secured the Swatch TTR world title by winning the Oakley Arctic Challenge in March 2010.',array['https://www.guinnessworldrecords.com/world-records/102159-most-men%E2%80%99s-ttr-world-snowboard-tour-titles','https://www.worldsnowboardfederation.org/ttr-winner-of-oakley-arctic-challenge-petuu-piiroinen-secures-swatch-ttr-world/']::text[],'verified')
