insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2012','ttr-world-snowboard-tour',2012,'2011/12 World Snowboard Tour season',null,null,null,null,null,'multiple','{}'::text[],'held',null,'TTR''s 10th anniversary season. Highlight was the inaugural World Snowboarding Championships at Oslo Vinterpark in February 2012, developed and owned by TTR and the World Snowboard Federation and run as a 6Star tour event - the first world championships organised by snowboarders since 1999. The Burton European Open was postponed to March, making WCS qualification difficult.',array['https://web.archive.org/web/20220302222719/https://worldsnowboardtour.com/history/']::text[],'verified')
on conflict (edition_id) do update set series_id=excluded.series_id,year=excluded.year,edition_label=excluded.edition_label,start_date=excluded.start_date,end_date=excluded.end_date,date_precision=excluded.date_precision,venue=excluded.venue,city=excluded.city,country=excluded.country,disciplines=excluded.disciplines,status=excluded.status,status_note=excluded.status_note,notes=excluded.notes,sources=excluded.sources,confidence=excluded.confidence,updated_at=now();
insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2013','ttr-world-snowboard-tour',2013,'2012/13 World Snowboard Tour season',null,null,null,null,null,'multiple',array['halfpipe','slopestyle','big-air','quarterpipe']::text[],'held',null,'First season under the new name. TTR announced on 2-4 July 2012 that the TTR World Tour would be called the World Snowboard Tour from the 2012/13 season; TTR president Reto Lamm said the tour then covered around 350 events across five continents. Headline events named in the announcement were Air & Style Beijing and Innsbruck, Burton European and US Open, O''Neill Evolution Davos and The Arctic Challenge Oslo.',array['https://www.worldsnowboardfederation.org/news/ttr-world-tour-becomes-world-snowboard-tour/','https://whitelines.com/archive/news/ttr-rebrands-to-world-snowboard-tour.html']::text[],'verified')
