insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2014','ttr-world-snowboard-tour',2014,'2013/14 World Snowboard Tour season',null,null,null,null,null,'multiple',array['halfpipe','slopestyle','big-air']::text[],'held',null,'Season in which the six star tiers were replaced by four event categories: Regional, National, International and Elite.',array['https://de.wikipedia.org/wiki/TTR_World_Snowboard_Tour']::text[],'likely')
