insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2015','ttr-world-snowboard-tour',2015,'2014/15 World Snowboard Tour season',null,null,null,null,null,'multiple','{}'::text[],'held',null,'First season under the new tour concept agreed at the May 2014 General Assembly in Barcelona: six star tiers replaced by four categories (Regional, National, International, Elite), with the Elite events forming the WST Pro Series. Titles were awarded in slopestyle and halfpipe only, at the Burton US Open on 8 March 2015.',array['https://web.archive.org/web/20220302222719/https://worldsnowboardtour.com/history/']::text[],'verified')
