insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('ttr-world-snowboard-tour--2017','ttr-world-snowboard-tour',2017,'2016/17 World Snowboard Tour season',null,null,null,null,null,'multiple',array['halfpipe','slopestyle','big-air']::text[],'held','Final season before the tour brand was retired.','TTR Pro Snowboarding restricted access to the World Snowboard Points List in January 2017 to force the snowboard industry to fund it. The merger with the WSF was announced 25 May 2017; from the 2017/18 season the merged organisation offered direct membership and the World Snowboard Tour brand ceased to exist.',array['https://www.sgieurope.com/world-snowboarding-will-replace-the-world-snowboard-tour/60795.article','https://www.worldsnowboardfederation.org/ttr-pro-snowboarding-and-world-snowboard-federation-create-one-joint-organisation/']::text[],'verified')
