insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--1983','us-open-snowboarding',1983,'1983 National Snowboarding Championships',null,null,null,'Snow Valley','Winhall','USA',array['slalom','downhill']::text[],'held',null,'No lift access; competitors hiked the hill. Andy Coghlan won men''s slalom and downhill. Several sources describe this, not 1982, as the first edition of what became the US Open, and Burton''s own later edition numbering (2002 = 20th, 2009 = 27th, 2012 = 30th, 2020 = 38th) counts from 1983.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://thesnowpros.org/2024/09/from-the-archives-great-moments-in-snowboarding-history-part-2/','https://www.firsttracksonline.com/2002/03/03/the-u-s-open-snowboarding-championships-back-to-where-it-all-began/','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s']::text[],'likely')
