insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--1985','us-open-snowboarding',1985,'1985 US Open Snowboarding Championships',null,null,null,'Stratton Mountain','Stratton','USA',array['slalom','downhill']::text[],'held',null,'First year at Stratton Mountain and the year the event was formally called the US Open Snowboarding Championships. Riders began wearing speed suits. Tom Sims won men''s slalom; Andy Coghlan defended the downhill.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.burton.com/en-us/blogs/the-burton-blog/13-firsts-us-open-snowboarding-championships','https://www.skihall.com/hall-of-famers/tom-sims/']::text[],'verified')
