insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--1998','us-open-snowboarding',1998,'1998 US Open Snowboarding Championships',null,null,null,'Stratton Mountain','Stratton','USA',array['halfpipe','big-air','boardercross']::text[],'held',null,'Remembered as ''the Year of the Mist'' for heavy fog. Boardercross debuted. Rob Kingwill won the men''s halfpipe; Nicola Thost, the 1998 Olympic champion, won the women''s. Mike Michalchuk''s back-to-back 1620s are cited by Burton as an early double-cork-era moment.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.burton.com/en-us/blogs/the-burton-blog/13-firsts-us-open-snowboarding-championships']::text[],'likely')
