insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--1999','us-open-snowboarding',1999,'1999 US Open Snowboarding Championships',null,null,null,'Stratton Mountain','Stratton','USA',array['halfpipe']::text[],'held',null,'Ross Powers won the men''s halfpipe with McTwists and 900s; Nicola Thost won the women''s for a second consecutive year.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/']::text[],'likely')
