insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2000','us-open-snowboarding',2000,'2000 US Open Snowboarding Championships',null,null,null,'Stratton Mountain','Stratton','USA',array['halfpipe']::text[],'held',null,'First superpipe at the US Open, reported as roughly 300 feet long with 15-foot walls. Guillaume Morisset and Natasza Zurek won for Canada. Recorded as halfpipe; the pipe event was run as a superpipe from this year.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/']::text[],'likely')
