insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2001','us-open-snowboarding',2001,'2001 US Open Snowboarding Championships',null,null,null,'Stratton Mountain','Stratton','USA',array['halfpipe']::text[],'held',null,'Danny Kass won the men''s halfpipe, narrowly over Vermont''s Abe Teter. Natasza Zurek took a second consecutive women''s title.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/']::text[],'likely')
