insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2002','us-open-snowboarding',2002,'2002 US Open Snowboarding Championships','2002-03-14','2002-03-17','day','Stratton Mountain','Stratton','USA',array['halfpipe','quarterpipe','boardercross','slopestyle']::text[],'held',null,'Held a month after the Salt Lake City Olympics, with a reported 30,000-plus spectators. Kelly Clark won quarterpipe and halfpipe; Danny Kass defended the men''s halfpipe. First Tracks called it the 20th year of the competition, which counts from 1983. [v0.2: MountainZone reports the first US Open slopestyle finals on 17 March 2002, with both podiums; discipline list corrected.]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.firsttracksonline.com/2002/03/03/the-u-s-open-snowboarding-championships-back-to-where-it-all-began/']::text[],'verified')
