insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2003','us-open-snowboarding',2003,'2003 US Open Snowboarding Championships','2003-03-11','2003-03-16','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','rail-jam']::text[],'held',null,'First rail jam at the US Open, won by Travis Rice; first live television broadcast; Philips became the first title sponsor. Ross Powers won the halfpipe, Gretchen Bleiler the women''s, Shaun White the slopestyle. MountainZone''s contemporaneous slopestyle report is dated 2003-03-15; full event dates not sourced. [v0.3 archive: Open Championships of Snowboarding 2003 calendar: "Mar 11 - 16, 2003 Stratton, VT". The usopen03 schedule page confirms Rail Jam final Friday 14 March, halfpipe finals Saturday 15 March, slopestyle finals Sunday 16 March.] [v0.3 archive: Open Championships of Snowboarding 2003 calendar: "Mar 11 - 16, 2003 Stratton, VT". The usopen03 schedule page confirms Rail Jam final Friday 14 March, halfpipe finals Saturday 15 March, slopestyle finals Sunday 16 March.]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.mountainzone.com/2003/usopen/html/usopen_slopestyle.html','https://web.archive.org/web/20030205093000/http://www.opensnowboarding.com/']::text[],'likely')
