insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2004','us-open-snowboarding',2004,'2004 US Open Snowboarding Championships','2004-03-16','2004-03-21','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','rail-jam']::text[],'held',null,'Women rode the rail jam for the first time; Leanne Pelosi won. Danny Kass won the halfpipe and the overall title; Kelly Clark won the women''s halfpipe. Priscilla Levac and Jake Blauvelt won slopestyle. [v0.3 archive: 2004 Open Championships of Snowboarding calendar: "Philips US Open March 16-21, 2004 Stratton, VT USA".] [v0.3 archive: 2004 Open Championships of Snowboarding calendar: "Philips US Open March 16-21, 2004 Stratton, VT USA".]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://web.archive.org/web/20040205215129/http://www.opensnowboarding.com/']::text[],'likely')
