insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2005','us-open-snowboarding',2005,'2005 US Open Snowboarding Championships','2005-03-14','2005-03-20','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','rail-jam']::text[],'held',null,'Danny Kass became the first rider to win four US Open halfpipe titles. Janna Meyen won her first title since 1991. [v0.3 archive: Open Championships of Snowboarding calendar: "US Open Mar. 14-20, 2005 Stratton, VT USA". The usopen05 schedule page runs Monday March 14th (practice) to Sunday March 20th.] [v0.3 archive: Open Championships of Snowboarding calendar: "US Open Mar. 14-20, 2005 Stratton, VT USA". The usopen05 schedule page runs Monday March 14th (practice) to Sunday March 20th.]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://web.archive.org/web/20050113043806/http://www.opensnowboarding.com/']::text[],'likely')
