insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2006','us-open-snowboarding',2006,'2006 US Open Snowboarding Championships','2006-03-14','2006-03-19','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','quarterpipe']::text[],'held',null,'Shaun White won halfpipe and slopestyle. The quarterpipe was revived, won by Danny Davis and Hana Beaman. White and Beaman took Most Valuable Rider awards. [v0.3 archive: Open Championships of Snowboarding calendar: "US Open March 14-19, 2006 Stratton, VT USA".] [v0.3 archive: Open Championships of Snowboarding calendar: "US Open March 14-19, 2006 Stratton, VT USA".]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://web.archive.org/web/20060213052702/http://www.opensnowboarding.com/']::text[],'likely')
