insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2007','us-open-snowboarding',2007,'2007 US Open Snowboarding Championships','2007-03-12','2007-03-18','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle']::text[],'held',null,'Marked by Burton as the 25th anniversary. Shaun White and Torah Bright won the first Burton Global Open Series championship titles, USD 100,000 each. Kelly Clark won a third halfpipe title; Travis Rice and Jamie Anderson won slopestyle. [v0.3 archive: Burton Global Open Series press release: "US Open March 12-18, 2007 Stratton, VT, USA".] [v0.3 archive: Burton Global Open Series press release: "US Open March 12-18, 2007 Stratton, VT, USA".]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://web.archive.org/web/20061104145301/http://www.opensnowboarding.com/']::text[],'likely')
