insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2008','us-open-snowboarding',2008,'2008 US Open Snowboarding Championships','2008-03-01','2008-03-22','month','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','big-air']::text[],'held',null,'Total prize purse reported at USD 471,500. Rated 6Star on the Swatch TTR World Snowboard Tour. Slopestyle finals ran 2008-03-21 (Shaun White and Kjersti Buaas) with halfpipe finals the following day; the event''s start date was not sourced. Cheryl Maas and Tim Humphreys won big air.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.worldsnowboardfederation.org/burton-us-open-report/']::text[],'likely')
