insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2009','us-open-snowboarding',2009,'2009 US Open Snowboarding Championships','2009-03-16','2009-03-22','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','quarterpipe','other']::text[],'held',null,'Closing event of the 2008/09 Burton Global Open Series; dates as announced in the series calendar. AlpineZone called it the 27th US Open. Danny Kass won a record fifth halfpipe title; Torah Bright won a third. Chas Guldemond and Kjersti Buaas won slopestyle. A best trick contest and a junior jam were also run, recorded as ''other''.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://whitelines.com/archive/news/burton-global-open-series-08-09.html','https://www.alpinezone.com/news-and-featured-articles/local-stratton-riders-make-a-splash-at-the-27th-u-s-open-snowboarding-championships/']::text[],'likely')
