insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2010','us-open-snowboarding',2010,'2010 US Open Snowboarding Championships','2010-03-16','2010-03-21','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle']::text[],'held',null,'Halfpipe finals ran 2010-03-20 in a slushy pipe; full event dates not sourced. Kazuhiro Kokubo won his first halfpipe title and Kelly Clark became the first woman to win four. Mikkel Bang and Sina Candrian won slopestyle. [v0.3 archive: Burton Global Open Series calendar listed the US Open as March 16-21, 2010. Refines the existing 2010-03 value.] [v0.3 archive: Burton Global Open Series calendar listed the US Open as March 16-21, 2010. Refines the existing 2010-03 value.] [v0.3 QA: the archive citation was a Flash-only page containing no dates and has been removed. The dates rest on the live-web sources.]',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.snowboarder.com/news/2010-us-open-halfpipe-results-and-photos']::text[],'likely')
