insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2011','us-open-snowboarding',2011,'2011 US Open Snowboarding Championships','2011-03-07','2011-03-13','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','rail-jam']::text[],'held',null,'Kazuhiro Kokubo won a second consecutive halfpipe title and dedicated it to tsunami-hit Japan. Kelly Clark won a fifth consecutive halfpipe title and her first Burton Global Open Series championship. Eric Willett and Enni Rukajarvi won their first slopestyle titles.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.worldsnowboardguide.com/events/burton-us-open-2011.html']::text[],'verified')
