insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2012','us-open-snowboarding',2012,'2012 US Open Snowboarding Championships','2012-03-05','2012-03-11','day','Stratton Mountain','Stratton','USA',array['halfpipe','slopestyle','rail-jam']::text[],'held',null,'Last US Open at Stratton after 28 editions there. Hit by a freak snowstorm. Shaun White won halfpipe; Elena Hight ended Kelly Clark''s streak; Seb Toots and Jamie Anderson won slopestyle; Chas Guldemond and Kjersti Buaas won The Jam. A veterans'' race, the Washed Up Cup, was run on the Friday night.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://www.methodmag.com/events/burton-us-open-2012.html']::text[],'verified')
