insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2013','us-open-snowboarding',2013,'2013 US Open Snowboarding Championships','2013-02-25','2013-03-02','day','Vail Mountain','Vail','USA',array['halfpipe','slopestyle']::text[],'held',null,'First US Open at Vail after 28 years in Vermont. Over USD 340,000 in prize money. Mark McMorris won his first slopestyle title, Spencer O''Brien the women''s; Shaun White won the halfpipe with 14-year-old Ayumu Hirano second.',array['https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/','https://snowboardmag.com/stories/burton-us-open-snowboarding-championships-announces-schedule-and-formats']::text[],'verified')
