insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2014','us-open-snowboarding',2014,'32nd Burton US Open (2014)','2014-03-03','2014-03-08','day','Vail Mountain','Vail','USA',array['halfpipe','slopestyle']::text[],'held',null,'Slopestyle finals 2014-03-07, halfpipe finals 2014-03-08. Mark McMorris won a second consecutive slopestyle; Jamie Anderson won the women''s; Kelly Clark won the halfpipe.',array['https://snowboardmag.com/stories/2014-burton-us-open-snowboarding-championships-roster','https://shop-eat-surf-outdoor.com/news/2014-03-relive-the-32nd-burton-us-open-on-burton-com-and-fox-sports-2/27965/','https://events.burton.com/burton-us-open/history/','https://www.aspentimes.com/sports/from-vermont-to-vail-a-look-back-at-the-36-year-history-of-the-burton-u-s-open-returning-march-5-10/']::text[],'verified')
