insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2020','us-open-snowboarding',2020,'38th Burton US Open (2020)','2020-02-24','2020-02-29','day','Golden Peak, Vail Mountain','Vail','USA',array['halfpipe','slopestyle']::text[],'held',null,'The last US Open held. Run about four months after Jake Burton Carpenter''s death and dedicated to him. USD 373,000 prize purse. Junior jam halfpipe 2020-02-25; slopestyle finals 2020-02-28; halfpipe finals 2020-02-29.',array['https://www.thesebastianvail.com/guide-2020-burton-u-s-open/','https://www.vaildaily.com/news/is-vails-burton-us-open-competition-gone-for-good/']::text[],'verified')
