insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('us-open-snowboarding--2021','us-open-snowboarding',2021,'2021 Burton US Open (cancelled)','2021-03-01','2021-03-06','day','Vail Mountain','Vail','USA','{}'::text[],'cancelled','Cancelled; the event did not return to Vail afterwards.','Scheduled for 2021-03-01 to 2021-03-06 and cancelled. Burton later confirmed the US Open would not be returning to Vail and pointed to the new Burton Mystery Series, intended to be hosted in a different country each time. Vail had invested USD 490,000 in the 2020 event and did not budget for 2022.',array['https://www.vaildaily.com/news/is-vails-burton-us-open-competition-gone-for-good/']::text[],'verified')
