insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('usasa-national-championships--1990','usasa-national-championships',1990,'1990 USASA National Championships','1990-02-01','1990-02-01','month','Snow Valley','Running Springs','USA','{}'::text[],'held',null,'Snowboarder/TransWorld 1990s timeline: February 1990 at Snow Valley, California; a severe snowstorm stranded competitors and USASA president Chuck Allen led the rescue. No podium found. City given as Running Springs, California (Snow Valley''s town) - not confirmed in the sources opened. Not to be confused with Snow Valley, Vermont, which hosted the 1983 and 1984 National Snowboarding Championships.',array['https://www.snowboarder.com/news/snowboard-history-timeline-part-31990s']::text[],'likely')
