insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('vans-triple-crown-of-snowboarding--2000','vans-triple-crown-of-snowboarding',2000,'1999/2000 Vans Triple Crown of Snowboarding','1999-12-03','2000-02-27','day',null,null,'multiple',array['halfpipe','big-air','boardercross']::text[],'held',null,'Three stops: Breckenridge, Colorado 3-5 December 1999 (boardercross, big air with a USD 10,000 winner''s cheque, halfpipe); Mount Seymour, British Columbia 14-16 January 2000 (snowboard cross, halfpipe); Sierra-at-Tahoe, California 25-27 February 2000 (halfpipe). Overall titles to Ross Powers and Ina Poetzl, with a USD 10,000 overall prize.',array['https://www.mountainzone.com/snowboarding/2000/vans/index.html','https://www.mountainzone.com/snowboarding/2000/vans/breckenridge/']::text[],'verified')
