insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('waengl-taengl--2013','waengl-taengl',2013,'Waengl Taengl 2013 (not held)',null,null,null,null,'Mayrhofen, Zillertal','Austria','{}'::text[],'cancelled','The Aesthetiker announced a break from producing the event in 2013. Club president Steve Gruber: ''we felt we needed time to look at how we could step it up again to guarantee the next edition of the Waengl is kick arse, not an anti-climax.''','The crew said they would instead focus on youth development and new event formats.',array['https://www.worldsnowboardfederation.org/news/the-asthetikers-announce-a-break-from-the-wangl-tangl-in-2013/']::text[],'verified')
