insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('westbeach-classic--1989','westbeach-classic',1989,'1989 WestBeach Classic (first edition)',null,null,null,null,null,'Canada',array['halfpipe','big-air']::text[],'held',null,'First edition. Sources disagree on venue and format: Whistler Blackcomb''s own 60th anniversary timeline says the WestBeach Classic launched at Blackcomb in 1989 and that Ross Rebagliati won the halfpipe and landed the cover of TransWorld Snowboarding; photographer Dano Pendygrasse recalls the first event as a big air at Cypress Mountain. Venue left null pending a contemporaneous source.',array['https://www.whistlerblackcomb.com/explore-the-resort/discover/whistler-blackcomb-60-anniversary.aspx','https://parrot-point-8fe3.squarespace.com/stories/pipe-dreams','https://www.piquenewsmagazine.com/local-sports/westbeach-classic-not-on-2459602']::text[],'likely')
