insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-rookie-finals--2017','world-rookie-finals',2017,'2017 World Rookie Finals, Kitzsteinhorn','2017-04-04','2017-04-09','day','Kitzsteinhorn','Kaprun / Zell am See','Austria',array['slopestyle','halfpipe']::text[],'held',null,'First World Rookie Finals at the Kitzsteinhorn. Climax of a 2016/17 World Rookie Tour season of eleven qualifying events across Chile, Australia, Bulgaria, Scandinavia, the Alps, Japan and North America. Programme included social dinners, workshops and a final party alongside the contests.',array['https://www.worldsnowboardfederation.org/2017-world-rookie-finals-kitzsteinhorn-kaprun/']::text[],'verified')
