insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-rookie-tour--2015','world-rookie-tour',2015,'2014/15 World Rookie Tour season','2014-08-01','2015-04-01','month',null,null,'multiple',array['slopestyle','halfpipe']::text[],'held',null,'Eleven-stop season: South America Rookie Fest, Valle Nevado, Chile (Aug 2014); Australian Rookie Fest, Thredbo (Aug 2014); Iceripper Rookie Fest, Laax (Jan 2015); WSF World Rookie Fest, Livigno (Jan 2015); Bulgarian Rookie Fest, Pamporovo (Jan-Feb 2015); Transilvania Rookie Fest, Arena Platos, Romania (Feb 2015); Hellas Rookie Fest, Greece (Feb 2015); Trentino Rookie Fest, Monte Bondone (Feb-Mar 2015); Oslo Rookie Fest, Oslo Vinterpark (Feb-Mar 2015); Indy Park Rookie Fest, Nekoma, Japan (Mar 2015); and the 3Star Völkl World Rookie Finals, Ischgl (Apr 2015). Rookies were riders born 1997-1999, Groms 2000 and later. Events counted towards the TTR World Snowboard Tour.',array['https://www.worldrookietour.com/the-tour/']::text[],'verified')
