insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-rookie-tour--2024','world-rookie-tour',2024,'Livigno World Rookie Fest 2024 (19th edition)','2024-01-14','2024-01-16','day','Mottolino Snowpark and Snowpark20','Livigno','Italy',array['slopestyle','rail-jam']::text[],'held',null,'Recorded here as a stop rather than a full season row. Presentation Sunday 14 January, rail jam at the Snowpark20 city park in central Livigno on the Monday afternoon, finals at Mottolino Snowpark on Tuesday 16 January. Described as the nineteenth edition, which implies a first edition in 2006.',array['https://www.worldsnowboardfederation.org/the-new-snowboard-generation-shines-at-livigno-world-rookie-fest-2024/']::text[],'verified')
