insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-ski-snowboard-festival--1996','world-ski-snowboard-festival',1996,'1996 World Ski & Snowboard Festival (inaugural)','1996-04-01','1996-04-01','month','Whistler Village, Whistler Mountain and Blackcomb Mountain','Whistler','Canada',array['big-air','halfpipe','other']::text[],'held',null,'Inaugural festival, directed by Doug Perry. Ten days, 22 competitions, about 1,500 athletes. Consolidated existing spring events including the WestBeach Classic, the Whistler Cup and the Couloir Ski Race Extreme, and added a snowboard museum exhibit and around a dozen bands. First joint marketing initiative between the two rival mountains and the Whistler Resort Association.',array['https://whistlermuseum.org/2024/04/09/wssf-the-beginning/','http://www.watermarkinc.ca/twssfmedia/timecapsule/backgrounder.html','https://en.wikipedia.org/wiki/World_Ski_and_Snowboard_Festival']::text[],'verified')
