insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-ski-snowboard-festival--1997','world-ski-snowboard-festival',1997,'1997 World Ski & Snowboard Festival','1997-04-04','1997-04-13','day','Whistler Village, Whistler Mountain and Blackcomb Mountain','Whistler','Canada',array['big-air','halfpipe','other']::text[],'held',null,'Over 2,000 athletes. More than 8,000 spectators at the WestBeach Invitational Big Air at the base of Whistler Mountain. Added the Moving Pictures film festival, the Backbone Enduro Vertical Challenge and the all-night ''Heaven'' event in the Conference Centre ballroom. Record April skier numbers on both mountains.',array['https://whistlermuseum.org/2024/04/09/wssf-the-beginning/']::text[],'verified')
