insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-snowboarding-championships--2012','world-snowboarding-championships',2012,'2012 World Snowboarding Championships','2012-02-10','2012-02-19','day',null,'Oslo','Norway',array['slopestyle','halfpipe']::text[],'held',null,'Organised by Snowboard-VM 2012 AS, owned by The Arctic Challenge, the Norwegian Snowboard Federation and Oslo Vinterpark. Described as the first world championships run by snowboarders since 1999. The Arctic Challenge did not run under its own name in 2012 as far as the sources I opened show.',array['https://en.wikipedia.org/wiki/2012_World_Snowboarding_Championships','https://www.worldsnowboardfederation.org/ttr-world-snowboarding-championships-2012-highlights/']::text[],'verified')
