insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-snowboarding-championships--2016','world-snowboarding-championships',2016,'The World Championships of Snowboarding 2016','2016-03-08','2016-03-16','day','Yabuli','Yabuli, Heilongjiang','China',array['halfpipe','slopestyle','big-air']::text[],'held',null,'400 athlete spots across the three disciplines, allocated through national snowboard association quotas. Billed as the pinnacle event of the 2016 tour, and the meeting at which the TTR tour champions were crowned.',array['https://www.worldsnowboardfederation.org/the-world-championships-of-snowboarding-2016-2/']::text[],'verified')
