insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-snowboarding-championships-sims--1984','world-snowboarding-championships-sims',1984,'1984 World Snowboarding Championships',null,null,null,'Soda Springs Ski Bowl','Soda Springs','USA',array['halfpipe']::text[],'held',null,'Tahoe Quarterly states Terry Kidwell won the halfpipe at Soda Springs in 1984 and 1985; the Sierra Sun halfpipe history says Kidwell ''won the following two years'' after Eddie Hargraves'' 1983 win. No date, no full podium and no other disciplines confirmed.',array['https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/news/super-pipe-dreams-halfpipe-has-come-long-way-since-a-ditch-in-tahoe-city-in-the-70s/']::text[],'likely')
