insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-snowboarding-championships-sims--1985','world-snowboarding-championships-sims',1985,'1985 World Snowboarding Championships',null,null,null,'Soda Springs Ski Bowl','Soda Springs','USA',array['halfpipe']::text[],'held',null,'Second of Terry Kidwell''s two Soda Springs halfpipe wins per Tahoe Quarterly. Note that Breckenridge''s own history page claims Breckenridge ''hosts the first snowboard World Cup'' in 1985 - a different event from this championship, and itself disputed (see open questions).',array['https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause','https://www.sierrasun.com/news/super-pipe-dreams-halfpipe-has-come-long-way-since-a-ditch-in-tahoe-city-in-the-70s/']::text[],'likely')
on conflict (edition_id) do update set series_id=excluded.series_id,year=excluded.year,edition_label=excluded.edition_label,start_date=excluded.start_date,end_date=excluded.end_date,date_precision=excluded.date_precision,venue=excluded.venue,city=excluded.city,country=excluded.country,disciplines=excluded.disciplines,status=excluded.status,status_note=excluded.status_note,notes=excluded.notes,sources=excluded.sources,confidence=excluded.confidence,updated_at=now();
insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('world-snowboarding-championships-sims--1986','world-snowboarding-championships-sims',1986,'1986 World Snowboarding Championships','1986-03-01','1986-03-01','month','Breckenridge Ski Resort','Breckenridge','USA',array['halfpipe']::text[],'held',null,'First Breckenridge edition, March 1986, on a hand-dug halfpipe on Peak 9. Breckenridge had lifted its snowboarding ban in 1984, the first major Colorado resort to do so. Paul Alden persuaded Breckenridge management to accept the halfpipe as a legitimate competitive format; Swatch was a major sponsor and the event drew national media. Greg Stump filmed it for ''Maltese Flamingo'' (1986). Terry Kidwell is reported to have won the halfpipe again in 1986 after the championships moved to Colorado (Tahoe Quarterly) - treated here as unconfirmed, no result row written. No full podium found in any source opened. Sources give only the month, not the days.',array['https://snowbrains.com/breckenridge-resort-co-marks-40-years-of-snowboarding-history-with-new-worlds-competition/','https://snowbrains.com/snowboarding-pioneer-paul-alden-dies-aged-89/','https://www.tetonvalleynews.net/townnews/sport/a-founding-figure-of-organized-competitive-snowboarding-has-passed/article_db455d7f-ed68-46f1-a971-050e55e36410.amp.html','https://www.snowboarder.com/news/snowboard-history-timeline-part-21980s','https://tahoequarterly.com/ski-ride-2016/rebels-with-a-cause']::text[],'likely')
