insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('wsf-south-america-tour--2012','wsf-south-america-tour',2012,'WSF South America Tour 2012','2012-07-07','2012-10-26','day',null,null,'multiple',array['rail-jam','slopestyle','big-air']::text[],'held',null,'Seven stops: Urban Rail Jam, Parque Arauco, Santiago, Chile (7 Jul); Roxy Snow Jam, Valle Nevado (8 Aug); Columbia Slopestyle, Valle Nevado (11 Aug); Mall Sport South America Rookie Fest, Valle Nevado (26 Aug); Rip Curl The Gump Big Air Show, Valle Nevado (August, exact date not given); Rey del Park, El Colorado (2 Sep); and a 2-Star indoor slopestyle grand finale in Rio de Janeiro, Brazil (24-26 Oct). Counted for TTR and WSF ranking lists.',array['https://www.worldsnowboardfederation.org/winter-season-in-chile/']::text[],'verified')
