insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('x-games-norway--2016','x-games-norway',2016,'X Games Oslo 2016','2016-02-24','2016-02-28','day','Oslo Winter Park (snowboard superpipe) and Toyen (big air)','Oslo','Norway',array['superpipe','big-air']::text[],'held',null,'First X Games to stage summer and winter disciplines in the same city; skateboard street ran at the Skur 13 warehouse at Filipstad Harbour. Announcement coverage places snowboard superpipe at Oslo Winter Park on 26 February and snowboard/ski big air at Toyen on 27 February. First X Games to include women''s ski and snowboard big air.',array['http://www.labelnetworks.com/x-games-oslo-to-launch-in-february-2016-bringing-together-both-summer-and-winter-sports/','https://www.firsttracksonline.com/2015/11/09/x-games-expands-to-oslo/','https://whitelines.com/snowboard-culture/snowboard-events/x-games-oslo-2016-halfpipe-finals-results-photos.html','https://www.downdays.eu/events/behind-the-scenes/a-brief-history-of-the-x-games-in-europe/']::text[],'verified')
