insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('x-games-norway--2017','x-games-norway',2017,'X Games Norway 2017 (Hafjell)','2017-03-08','2017-03-11','day','Hafjell Alpinsenter','Oyer','Norway',array['slopestyle','big-air']::text[],'held',null,'Men''s and women''s snowboard slopestyle and big air. Hafjell Resort reports 17,500 spectators and Norwegian athletes taking 3 gold, 2 silver and 1 bronze of 8 golds. No superpipe.',array['https://de.wikipedia.org/wiki/X-Games_Norway_2017','https://www.hafjellresort.no/en/x-games']::text[],'verified')
