insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('x-games-norway--2018','x-games-norway',2018,'X Games Norway 2018 (Oslo)','2018-05-16','2018-05-20','day','Telenor Arena, Fornebu','Oslo','Norway',array['big-air']::text[],'held',null,'Indoor/urban big air edition held in May. Dates are taken from the title of an ESPN Press Room release (''SAVE THE DATE: X Games Norway 2018 May 16-20 in Oslo''); espnpressroom.com returned HTTP 403 to this researcher so the body of the release was not read. Venue attribution to Telenor Arena is inferred from the 2019 edition and is NOT confirmed - treat as unverified.',array['https://espnpressroom.com/us/press-releases/2018/01/save-date-x-games-norway-2018-may-16-20-oslo/','https://espnpressroom.com/us/press-releases/2018/05/x-games-norway-2018-day-two-news-and-results-rookies-dominate-the-ski-and-snowboard-big-air-competitions/']::text[],'likely')
