insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('x-games-norway--2019','x-games-norway',2019,'X Games Norway 2019 (Oslo)','2019-08-31',null,'day','Telenor Arena, Fornebu','Oslo','Norway',array['big-air']::text[],'held',null,'Indoor edition combining winter and summer disciplines under one roof: men''s and women''s snowboard and ski big air, skateboard street, and Moto X. Only 31 August 2019 was confirmed as a competition date; the event ran over more than one day and the full date range was not established.',array['https://radseason.com/event/x-games-norway-fornebu-norway/','https://espnpressroom.com/us/press-releases/2019/08/x-games-norway-2019-news-and-results-ski-and-snowboard-big-air-skateboard-street-and-moto-x-best-trick-best-whip-and-quarterpipe-high-air/']::text[],'likely')
