insert into public.event_editions (edition_id,series_id,year,edition_label,start_date,end_date,date_precision,venue,city,country,disciplines,status,status_note,notes,sources,confidence) values ('x-games-norway--2020','x-games-norway',2020,'X Games Norway 2020 (Hafjell)','2020-03-07','2020-03-08','day','Hafjell Alpinsenter','Oyer','Norway',array['big-air','slopestyle','other']::text[],'held',null,'Big air on the Saturday, slopestyle on the Sunday, including a Knuckle Huck (recorded as ''other''). Final X Games Norway edition. Mark McMorris took his 19th career X Games medal with gold in snowboard big air here, passing Shaun White''s winter medal record.',array['https://www.hafjellresort.no/en/x-games','https://espnpressroom.com/us/press-releases/2020/03/x-games-norway-2020-day-two-news-and-results/','https://en.wikipedia.org/wiki/X_Games']::text[],'verified')
